DROP TABLE IF EXISTS Leetcode.SimilarQuestion;
DROP TABLE IF EXISTS Leetcode.QuestionCompany;
DROP TABLE IF EXISTS Leetcode.QuestionTopic;
DROP TABLE IF EXISTS Leetcode.LikeDislike;
DROP TABLE IF EXISTS Leetcode.Discussion;
DROP TABLE IF EXISTS Leetcode.Question;
DROP TABLE IF EXISTS Leetcode.Company;
DROP TABLE IF EXISTS Leetcode.Difficulty;
DROP TABLE IF EXISTS Leetcode.Topic;
DROP TABLE IF EXISTS Leetcode.[User];


DROP SCHEMA IF EXISTS Leetcode;
GO

CREATE SCHEMA Leetcode;
GO

CREATE TABLE Leetcode.Company
(
    id   int PRIMARY KEY IDENTITY (1,1),
    name varchar(21) NOT NULL
);

CREATE TABLE Leetcode.Difficulty
(
    id   int PRIMARY KEY IDENTITY (1,1),
    name varchar(6) NOT NULL
);

CREATE TABLE Leetcode.Topic
(
    id   int PRIMARY KEY IDENTITY (1,1),
    name varchar(20) NOT NULL
);

CREATE TABLE Leetcode.[User]
(
    id   int PRIMARY KEY IDENTITY (1,1),
    name varchar(26) NOT NULL
);

CREATE TABLE Leetcode.Question
(
    id                          int PRIMARY KEY IDENTITY (1,1),
    title                       varchar(79)   NOT NULL,
    description                 varchar(5000) NOT NULL,
    isPremium                   bit           NOT NULL DEFAULT 0,
    difficultyId                int           NOT NULL,
    frequency                   float         NOT NULL,
    questionSlug                varchar(89)   NOT NULL,
    numberOfAcceptedSubmissions varchar(15)   NOT NULL,
    numberOfSubmissions         varchar(15)   NOT NULL,
    CONSTRAINT FK_Question_Difficulty FOREIGN KEY (difficultyId) REFERENCES Leetcode.Difficulty (id)
);

CREATE TABLE Leetcode.Discussion
(
    id            int PRIMARY KEY IDENTITY (1,1),
    solution      varchar(5000) NOT NULL,
    title         varchar(98)   NOT NULL,
    userId        int           NOT NULL,
    questionId    int           NOT NULL,
    numberOfViews int           NOT NULL,
    CONSTRAINT FK_Discussion_User FOREIGN KEY (userId) REFERENCES Leetcode.[User] (id),
    CONSTRAINT FK_Discussion_Question FOREIGN KEY (questionId) REFERENCES Leetcode.Question (id)
);

CREATE TABLE Leetcode.LikeDislike
(
    questionId int NOT NULL,
    userId     int NOT NULL,
    score      int NOT NULL,
    CONSTRAINT PK_LikeDislike PRIMARY KEY (questionId, userId),
    CONSTRAINT FK_LikeDislike_Question FOREIGN KEY (questionId) REFERENCES Leetcode.Question (id),
    CONSTRAINT FK_LikeDislike_User FOREIGN KEY (userId) REFERENCES Leetcode.[User] (id)
);

CREATE TABLE Leetcode.QuestionCompany
(
    questionId INT NOT NULL,
    companyId  INT NOT NULL,
    CONSTRAINT PK_QuestionCompany PRIMARY KEY (questionId, companyId),
    CONSTRAINT FK_QuestionCompany_Question FOREIGN KEY (questionId) REFERENCES Leetcode.Question (id),
    CONSTRAINT FK_QuestionCompany_Company FOREIGN KEY (companyId) REFERENCES Leetcode.Company (id)
);

CREATE TABLE Leetcode.QuestionTopic
(
    questionId INT NOT NULL,
    topicId    INT NOT NULL,
    CONSTRAINT PK_QuestionTopic PRIMARY KEY (questionId, topicId),
    CONSTRAINT FK_QuestionTopic_Question FOREIGN KEY (questionId) REFERENCES Leetcode.Question (id),
    CONSTRAINT FK_QuestionTopic_Topic FOREIGN KEY (topicId) REFERENCES Leetcode.Topic (id)
);

CREATE TABLE Leetcode.SimilarQuestion
(
    questionId        INT NOT NULL,
    similarQuestionId INT NOT NULL,
    CONSTRAINT PK_SimilarQuestion PRIMARY KEY (questionId, similarQuestionId),
    CONSTRAINT FK_SimilarQuestion_Question_questionId FOREIGN KEY (questionId) REFERENCES Leetcode.Question (id),
    CONSTRAINT FK_SimilarQuestion_Question_similarQuestionId FOREIGN KEY (similarQuestionId)
        REFERENCES Leetcode.Question (id)

);

