INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (2, N'class Solution:
def twoSum(self, nums: List[int], target: int) -> List[int]:
    store = dict()
    for i in range(len(nums)):
        sec = target - nums[i]
        if sec not in store:
            store[nums[i]]=i
        else:
            return [store[sec],i]', N'?? Simple || 100% faster || 5 Lines code || Well-Explained ????', 351, 1, 6800);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (3, N'class Solution:
def twoSum(self, nums: List[int], target: int) -> List[int]:
    tmp = sorted(nums)
    n, i, j = len(nums), 0, (n-1)
    while True:
        s = tmp[i]+tmp[j]
        if s>target:
            j-=1
        elif s<target:
            i+=1
        else:
            break
    return [nums.index(tmp[i]),n-(nums[::-1].index(tmp[j]))-1]', N'?? Simple || 100% faster || 5 Lines code || Well-Explained ????', 351, 1, 6800);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (4, N'class Solution:
