            prevMap[n] = i', N'Easy python3 using enumerate(updated)', 67, 1, 513);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (14, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        inverses = {}
        for i, num in enumerate(nums):
            if num in inverses:
