INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (15, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        #two pointer technique with sorting -> time -> O(nlogn)
        #hashing technique -> time -> O(n)
        di = {}
        for i in range(len(nums)):
            if target-nums[i] in di:
                return [di[target-nums[i]], i]
            else:
                di[nums[i]] = i
        #no need we will find solution in loop itself acc. to the question', N'Python | Easy | O(n)', 193, 1, 1600);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (16, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        for i in nums:
            if target - i in nums[nums.index(i) + 1:]: return [nums.index(i), nums[nums.index(i) + 1:].index(target - i) + nums.index(i) + 1]', N'Accepted Python3 solution with 2 lines', 119, 1, 608);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (17, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
		# construnct a empty hash map
        val_index_map = {}
		# hasmpa { value: index}
		# iterate through given array with count, I used enumerate for count you guys can also add its mannually 
        for count, num in enumerate(nums):
			# first i check the diff btw target and current value
            req_diff = target - num
			# if required difrence is exist in hashmap, then we are done 
            if req_diff in val_index_map:
				# so current_value + required_diff  = Traget 
				# mission accomplished
                return [val_index_map.get(req_diff), count]
            else:
				# if required diff is not present in the hasmap then we add current number as a value and  its index as a key
                val_index_map[num] = count
        return', N'Python solution using hash map with O(n) complexity', 15, 1, 929);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (18, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        """Take each number and check if its complement has been seen before. If not,
        add it to the list of known complements along with its index.

        Args:
            nums (List[int]): Input array of integers
            target (int): Target integer

        Returns:
            List[int]: Indices of the two integers that sum to target
        """
        # Initialise hash map to store known integers
        complements = {}
        # Iterate through the list
        for i in range(len(nums)):
            # Check if the current number''s complement has been seen before
            complement = target - nums[i]
            if complement in complements:
                return [complements[complement], i]
            # Add the current number to the list of known complements
            complements[nums[i]] = i', N'?? [Python] Hash table - O(n) | Full explanation ?', 404, 1, 613);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (19, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        """Take each pair of numbers and see if they add up to the target.

        Args:
            nums (List[int]): Input array of integers
            target (int): Target integer

        Returns:
            List[int]: Indices of the two integers that sum to target
        """
        # Get length of input array
        n = len(nums)
        # Iterate over all pairs (i,j)
        for i in range(n):
            for j in range(i + 1, n):
                # Check if this pair equals the target
                if nums[i] + nums[j] == target:
                    return [i, j]', N'?? [Python] Hash table - O(n) | Full explanation ?', 404, 1, 613);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (20, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
