INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (26, N'class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        seen = dict() #hash table of value-index pair 
        for i, num in enumerate(nums):
            x = target - num #residual
            if x in seen: return [seen[x], i]
            seen[num] = i
        return None', N'[Python3/C++] hash table', 4, 1, 774);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (27, N'class Solution:
    def twoSum(self, N: List[int], t: int) -> List[int]:
