INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (60, N'class Solution:
	def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:

		# base cases
		if l1==None:
			return l2
		if l2==None:
			return l1

		curr = ListNode(0)
		head = curr
		carry = 0
		while l1  and l2: 
			total = 0
			total += carry + l1.val + l2.val
			curr.next = ListNode(total%10)
			carry = total // 10
			curr = curr.next
			l1 = l1.next
			l2 = l2.next

		while (l1):
			total = 0
			total += carry + l1.val
			curr.next = ListNode(total%10)
			carry = total // 10
			curr = curr.next
			l1 = l1.next

		while (l2):
			total = 0
			total += carry + l2.val
			curr.next = ListNode(total%10)
			carry = total // 10
			curr = curr.next
			l2 = l2.next

		if carry:
			curr.next = ListNode(carry)

		return head.next', N'python3 : Easy to understand and straight forward approach', 451, 2, 353);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (61, N'class Solution:
    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
        
        
        # Keep a dummy head for your return
        sentinel = ListNode(0)
        curr = sentinel
        # Initializes two pointers pointing to two lists seperately
        node1, node2 = l1, l2
        # Check if we need add ''1'' to next calculation
        carry = False
        
        
        while node1 or node2:
            # Calculate the current sum, if node is None then initializes to 0
            i = node1.val if node1 else 0
            y = node2.val if node2 else 0
            total = i + y
            
            # Check carry and update current sum
            if carry:
                total += 1
                carry = False
                
            # Modify total sum to one digit number and update carry
            if total >= 10:
                carry = True
                total -= 10
                
            # Initializes a new node based on current sum and link to the dummy head
            
            to_add = ListNode(total)
            curr.next = to_add
            curr = to_add
            
            # Update node1 and node2 for next calculation
            node1 = node1.next if node1 else None
            node2 = node2.next if node2 else None
        
        # Check carry at the end of calculation
        if carry:
            extraDigit = ListNode(1)
            curr.next = extraDigit
            
            
        
        return sentinel.next', N'python3 easy solution with detailed comments, faster than 96.55%', 582, 2, 554);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (62, N'class Solution:
def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
    first_num=[]
    second_num=[]
    while l1 is not None:
        first_num.append(l1.val)
        l1=l1.next
    while l2 is not None:
        second_num.append(l2.val)
        l2=l2.next
    first_num.reverse()
    second_num.reverse()
    res1=int(''''.join(map(str,first_num)))
    res2=int(''''.join(map(str,second_num)))
    res3=str(res1+res2)
    l3=None
    for i in res3:
        data=int(i)
        newnode=ListNode(data)
        if not l3:
            l3=newnode
        else:
            newnode.next=l3
            l3=newnode
    return l3', N'Python3 solution', 285, 2, 453);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (63, N'class Solution:  
    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
        result = ListNode()
        result_tail = result
        carry = 0
        
        while l1 or l2 or carry:
            val1 = l1.val if l1 else 0
            val2 = l2.val if l2 else 0
            
            out = (val1 + val2 + carry) % 10
            carry = (val1 + val2 + carry) // 10
            
            result_tail.next = ListNode(out)
            
            result_tail = result_tail.next
            l1 = l1.next if l1 else None
