INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (68, N'class Solution:
    def addTwoNumbers(self, l1, l2):
        """
        :type l1: ListNode
        :type l2: ListNode
        :rtype: ListNode
        """
        # O(n) and O(1)
        head = l1
        
        carry, l1.val = divmod(l1.val + l2.val, 10)
        while l1.next and l2.next:
            l1 = l1.next
            l2 = l2.next
            carry, l1.val = divmod(l1.val + l2.val + carry, 10)
        
        if l2.next:
            l1.next = l2.next
        
        while l1.next:
            l1 = l1.next
            carry, l1.val = divmod(l1.val + carry, 10)
        
        if carry:
            l1.next = ListNode(carry)
        
        return head', N'Python, O(n) and in-place, beat 96%', 26, 2, 546);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (69, N'class Solution:
