            h1.val = sm%10
            prev = h1
            h1 = h1.next
            h2 = h2.next
            
        if h2!=None:
            h1 = h2 
            #since we are overriding the first linked list, so our priority is on head1
            if prev!=None:
                #if case will handle this edge case l1 = [] l2 = [1,2,3]
