INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (71, N'class Solution:
    
    def addTwoNumbers(self, l1: ListNode, l2: ListNode, over=0) -> ListNode:
        if l1 is None and l2 is None:
            if over > 0:
                return ListNode(over)
            return None
        
        num = over
        next1 = None
        next2 = None
        
        if not l1 is None:
            num += l1.val
            next1 = l1.next
        
        if not l2 is None:
            num += l2.val
            next2 = l2.next
        
        node = ListNode(num)
        over = 0
        if node.val > 9:
            over = 1
            node.val -= 10
        
        node.next = self.addTwoNumbers(next1, next2, over)
        
        return node', N'Python faster than 100% and easy to read', 175, 2, 595);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (72, N'class Solution:  # Time: O(n) and Space: O(n)
    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
        dummy = cur = ListNode()  # Creating a new node to store l1 + l2 values, dummy will give us head address &amp; cur will be used to append new nodes
        carry = 0

        while l1 or l2 or carry:  # we will continue till either one of these have positive values left 
            v1 = l1.val if l1 else 0
            v2 = l2.val if l2 else 0

            # Addition: New digits
            val = v1 + v2 + carry     # in 1st iteration carry will be 0, but in next iterations previous iter generated carry will be added
            carry = val // 10         # if val = 15 then 15//10 = 1 ie. (1.5)
            val = val % 10            # 15 % 10 = 5
            cur.next = ListNode(val)  # dummy/cur --> val

            # Update pointers
            cur = cur.next            # dummy --> val/cur
            l1 = l1.next if l1 else None
            l2 = l2.next if l2 else None

        return dummy.next', N'Python O(n) Time-Space Solution', 28, 2, 221);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (73, N'class Solution:
