INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (76, N'class Solution:
    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
        def lstIter(lst):
            while lst is not None:
                yield lst.val
                lst = lst.next
        head = prev = ListNode(0)
        carry = 0
        for x in (ListNode(sum(x)) for x in zip_longest(lstIter(l1), lstIter(l2), fillvalue=0)):
            prev.next = prev = x
            x.val, carry = (carry + x.val) % 10, (carry + x.val) // 10
        if carry:
            prev.next = ListNode(carry)
        return head.next', N'Brief and pythonic', 530, 2, 110);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (77, N'class Solution:
	def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
