INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (86, N'class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
                        
        queue = collections.deque([])        
        window = set()
        result = 0
        
        for c in s:            
            if c in window:
                while queue:
                    prev = queue.popleft()
                    window.remove(prev)
                    if prev == c:
                        break
                            
            queue.append(c)
            window.add(c)
            result = max(result, len(window))
            
        return result', N'Python Interview Thought Process: O(2^n) -> O(n)', 502, 3, 1300);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (87, N'class Solution:
