		hash_map = dict() # hash map is to store the latest index of char

		for i in range(len(s)):
			if s[i] in hash_map and start < hash_map[s[i]]:  
				start = hash_map[s[i]] 
			hash_map[s[i]] = i 
			if i - start > longest: 
				longest = i - start 

		return longest', N'Python3 Hashmap easy solution | faster than 99.94%', 21, 3, 607);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (96, N'class Solution(object):
    def lengthOfLongestSubstring(self, s):
        mostRecentIndexofChar = {}
        longest = 0
        firstGoodIndex = 0
        
        for index in range(len(s)):
            
            if firstGoodIndex > index:
                continue
                
            if s[index] in mostRecentIndexofChar:
                firstGoodIndex = max(firstGoodIndex, mostRecentIndexofChar[s[index]])
            
            longest = max(longest, index - firstGoodIndex + 1)
            
            mostRecentIndexofChar[s[index]] =  index + 1
        
        return longest', N'[Python] Sliding Window O(n) beats 96.91% (Explanation)', 598, 3, 356);
