INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (104, N'class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        seen = {}
        left = 0
        output = 0
        for right, char in enumerate(s):
            # If char not in seen dictionary, we can keep increasing the window size by moving right pointer
            if char not in seen:
                output = max(output, right - left + 1)

            # There are two cases if `char` in seen:
            # case 1: char is inside the current window, we move left pointer to seen[char] + 1.
            # case 2: char is not inside the current window, we can keep increase the window
            else:
                if seen[char] < left:
                    output = max(output, right - left + 1)
                else:
                    left = seen[char] + 1

            seen[char] = right

        return output', N'Python3: Sliding window O(N) => Faster than 99.7%', 488, 3, 294);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (105, N'class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        substr = deque()
        index = set()
        max_len = 0
        for char in s:
            if char not in index:
                substr.append(char)
                index.add(char)
            else:
                while substr:
                    c = substr.popleft()
                    index.remove(c)
                    if c == char:
                        substr.append(char)
                        index.add(char)
                        break
            if len(substr) > max_len:
                max_len = len(substr)
        return max_len', N'Faster than 99.5% Python Solution', 197, 3, 332);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (106, N'class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        seen = {}
        l = 0
        output = 0
        for r in range(len(s)):
            """
            If s[r] not in seen, we can keep increasing the window size by moving right pointer
            """
            if s[r] not in seen:
                output = max(output,r-l+1)
            """
            There are two cases if s[r] in seen:
            case1: s[r] is inside the current window, we need to change the window by moving left pointer to seen[s[r]] + 1.
            case2: s[r] is not inside the current window, we can keep increase the window
            """
            else:
                if seen[s[r]] < l:
                    output = max(output,r-l+1)
                else:
                    l = seen[s[r]] + 1
            seen[s[r]] = r
        return output', N'[Fastest Solution Explained][0ms][100%] O(n)time complexity O(n)space complexity', 478, 3, 808);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (107, N'class Solution:
