INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (122, N'class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        def has_duplicates(start, end):
            seen = set()
            while start <= end:
                letter = s[start]
                if letter in seen:
                    return True
                else:
                    seen.add(letter)
                    start += 1
            return False
        
        n = len(s)
        longest = 0
        for start in range(n):
            for end in range(start, n):
                if not has_duplicates(start, end):
                    longest = max(longest, end - start + 1)
                    
        return longest', N'Python | Walkthrough + Complexity | Sliding Window', 334, 3, 520);
