INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (153, N'class Solution():
    def findMedianSortedArrays(self, nums1, nums2):
        
        combined = nums1 + nums2
        combined.sort()
        length = len(combined)

        if length % 2 == 0:
            length = (length / 2) - 1
            median = (combined[int(length)] + combined[int(length + 1)]) / 2
            
