INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (169, N'class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        n1 = len(nums1)
        n2 = len(nums2)
        n = n1 + n2

        p1 = 0
        p2 = n - 1
        
        a1 = 0
        a2 = n1 - 1
        
        b1 = 0
        b2 = n2 -1
        
        while p2 - p1 > 1:
            p1 += 1
            p2 -= 1
            
            if a2 < a1:
                b1 += 1
                b2 -= 1
                continue
            
            if b2 < b1:
                a1 += 1
                a2 -= 1
                continue

            if nums1[a1] <= nums2[b1]:
                a1 += 1
            else:
                b1 += 1

            if nums1[a2] > nums2[b2]:
                a2 -= 1
            else:
                b2 -= 1

        if p1 == p2:
            return sum(nums1[a1:a2+1]) if len(nums1[a1:a2+1])>0 else sum(nums2[b1:b2+1])
        
        return (sum(nums1[a1:a2+1]) + sum(nums2[b1:b2+1]))/2', N'Two-two-two pointers as if they were merged', 7, 4, 186);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (170, N'class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        
        m,n = len(nums1),len(nums2)
        
        if m+n<1:
            return -1
        
        merge = []
        i,j = 0,0
        
        while i<len(nums1) and j<len(nums2):
            if nums1[i]<=nums2[j]:
                merge.append(nums1[i])
                i+=1
            elif nums1[i]>=nums2[j]:
                merge.append(nums2[j])
                j+=1
        
        if len(nums1)>i:
            merge.extend(nums1[i:])
        else:
            merge.extend(nums2[j:])
                
        a = len(merge)
        if a==1:
            return merge[0]
        
        b = ceil(a/2)
        
        if a%2==0:
            return (merge[b]+merge[b-1])/2
		else:
		    return merge[b-1]', N'Python3 solution in time O(n+m)', 381, 4, 300);
