INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (178, N'class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        merged_list = self.merge_sort(nums1, nums2)

        len_merged_list = len(merged_list)

        # middle index and middle - 1 index
        mid = len_merged_list // 2
        # when the size is even
        if len_merged_list % 2 == 0:
            return (merged_list[mid] + merged_list[mid - 1]) / 2

        # when the size is odd
        return merged_list[mid]

    def merge_sort(self, num1: List[int], num2: List[int]):
        merged_list = []

        i = 0
        j = 0

        len_num1 = len(num1) - 1
        len_num2 = len(num2) - 1

        while i <= len_num1 and j <= len_num2:
            if num1[i] < num2[j]:
                merged_list.append(num1[i])
                i += 1
            else:
                merged_list.append(num2[j])
                j += 1

        while i <= len_num1:
            merged_list.append(num1[i])
            i += 1

        while j <= len_num2:
            merged_list.append(num2[j])
            j += 1

        return merged_list', N'Easy Python Solution', 293, 4, 4);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (179, N'class Solution:
    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:
        nums1.extend(nums2)
        nums = sorted(nums1)
        # nums = list(set(nums))
        m = len(nums)
        if m%2==0 and m>1:
            i = m//2
            med = (nums[i-1]+nums[i])/2
        elif m%2==1 and m>1:
            i = m//2
            med = nums[i]
        else:
            med = nums[0]
        
        return med', N'Python3 Solution', 604, 4, 2);
