        return res', N'Easy Python3 Two Pointer Solution w/ Explanation', 455, 5, 204);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (198, N'class Solution:
#     O(n^2) || space O(n)
    def longestPalindrome(self, string: str) -> str:
        if not string or len(string) < 1:
            return ''''
        
        start, end = 0, 0

        for i in range(len(string)):
            odd = self.expandFromMiddleHelper(string, i, i)
            even = self.expandFromMiddleHelper(string, i, i + 1)
            maxIndex = max(odd, even)
            if maxIndex > end - start:
                start = i - ((maxIndex - 1) // 2)
                end = i + (maxIndex // 2)
                
        return string[start:end + 1]



    def expandFromMiddleHelper(self, string, left, right):
        while left >= 0 and right < len(string) and string[left] == string[right]:
            left -= 1
            right += 1

        currentWindowSize = (right - left - 1) 
        return currentWindowSize', N'Python3  Runtime: 897ms  81.93% memory: 13.9mb 99.78%', 552, 5, 361);
