INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (205, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        longest = 0
        sub = ''''
        
        def expand(left, right):
            nonlocal longest, sub
            while left >= 0 and right < len(s) and s[left] == s[right]:
                length = right-left+1
                if length > longest:
                    longest = length
                    sub = s[left:right+1]
                    
                left -= 1
                right += 1
                    
        for i in range(len(s)):
            expand(i, i)
            expand(i, i+1)
            
        return sub', N'[Python 3] Expand from center', 138, 5, 230);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (206, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
       
        # Check if a string is palindrome
        # within the given index i to j
        def isPal(s,i,j):
            while i < j:
                if s[i] != s[j]:
                    break
                i += 1
                j -= 1
            else:
                return True
            return False
        
        # Init
        p = (0,0) # Portion of the string to be checked as palindrome
        n = len(s)
        
        # Base Case
        if n == 1:
            return s
        
        # Base Case
        if isPal(s,0,n-1):
            return s
        
        # For all other case
        for j in range(n):
            
            # Start from the begining
            i = 0
            
            # While current index i is less than
            # end index j
            while i < j:
                
                # Check for palindrome only if 
                # first and last character of a portion
                # of the string is similar
                if s[i] == s[j]:
                    
                    # Check if size of the current portion is
                    # greater then the last max palindrome string.
                    # Then check if this portion is palindrome.
                    # Update the portion with current indexes
                    if (p[1] - p[0]) < (j-i) and isPal(s,i,j):
                        p = (i,j)
                i += 1
        
        # Return the longest protion of the string found to be palindrome 
        return s[p[0]:p[1]+1]', N'[Py/Py3] Simple solution w/ comments', 230, 5, 665);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (207, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        answer = ""
        
        for i in range(len(s)):
            
            odd = self.palindrome(s, i, i)
            even = self.palindrome(s, i, i+1)
            
            large = odd if len(odd) > len(even) else even
            answer = large if len(large) >= len(answer) else answer
        return answer
        
        
        
    def palindrome(self, s, left, right):
        IndexL = 0
        IndexR = 0
        
        while left >= 0 and right < len(s):
            
            if s[left] == s[right]:
                IndexL = left
                IndexR = right
            else:
                break
            
            left -= 1
            right += 1
        return s[IndexL: IndexR+1]', N'Simple Python code || Faster than 70.29% of Python3', 646, 5, 439);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (208, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        length = len(s)
        dp = {}
        max_len = 1
        start = 0

        for _len in range(2, length + 1):
            i = 0
            while i <= length - _len:
                j = i + _len - 1
                if _len <= 3:
                    dp[(i, j)] = s[i] == s[j]
                elif s[i] == s[j]:
                    dp[(i, j)] = dp[(i + 1, j - 1)]
                else:
                    dp[(i, j)] = False

                if dp[(i, j)] and _len > max_len:
                    max_len = _len
                    start = i
                i += 1

        return s[start:start + max_len]', N'My simple and easy understanding DP Python solution', 413, 5, 802);
