INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (211, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        if not s:
            return ''''
        def extend(s:str, i:int, j:int) -> Tuple[int, int]:
            while i>=0 and j < len(s):
                if s[i] != s[j]:
                    break
                i -= 1
                j += 1
            return i+1, j-1
        indices  = [0,0]
        for  i in range(len(s)):
            l1, r1 = extend(s, i, i)
            if r1-l1 > indices[1] - indices[0]:
                indices = l1, r1
            if i+1 < len(s) and s[i]== s[i+1]:
                l2, r2 = extend(s, i, i+1)
                if r2-l2 > indices[1] - indices[0]:
                    indices = l2, r2
        return s[indices[0]:indices[1]+1]', N'Python', 384, 5, 2);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (212, N'class Solution:
 
    def longestPalindrome(self, text: str) -> str:
        N = len(text)
        if N == 0:
            return 
        if N == 1:
            return text
        N = 2*N+1 # Position count
        L = [0] * N
        L[0] = 0
        L[1] = 1
        C = 1	 # centerPosition
        R = 2	 # centerRightPosition
        i = 0 # currentRightPosition
        iMirror = 0	 # currentLeftPosition
        maxLPSLength = 0
        maxLPSCenterPosition = 0
        start = -1
        end = -1
        diff = -1

    
        for i in range(2,N):
        
            # get currentLeftPosition iMirror for currentRightPosition i
            iMirror = 2*C-i
            L[i] = 0
            diff = R - i
            # If currentRightPosition i is within centerRightPosition R
            if diff > 0:
                L[i] = min(L[iMirror], diff)

            # Attempt to expand palindrome centered at currentRightPosition i
            # Here for odd positions, we compare characters and
            # if match then increment LPS Length by ONE
            # If even position, we just increment LPS by ONE without
            # any character comparison
            try:
                while ((i + L[i]) < N and (i - L[i]) > 0) and \
                        (((i + L[i] + 1) % 2 == 0) or \
                        (text[(i + L[i] + 1) // 2] == text[(i - L[i] - 1) // 2])):
                    L[i]+=1
            except Exception as e:
                pass

            if L[i] > maxLPSLength:	 # Track maxLPSLength
                maxLPSLength = L[i]
                maxLPSCenterPosition = i

            # If palindrome centered at currentRightPosition i
            # expand beyond centerRightPosition R,
            # adjust centerPosition C based on expanded palindrome.
            if i + L[i] > R:
                C = i
                R = i + L[i]

        # Uncomment it to print LPS Length array
        # printf("%d ", L[i]);
        start = (maxLPSCenterPosition - maxLPSLength) // 2
        end = start + maxLPSLength - 1
        return text[start:end+1]', N'Manacher’s Algorithm || Python || Beats 98% || O(n) time', 606, 5, 5);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (213, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        n = len(s)
        res = ''''
        def find(i, j):
            nonlocal res
            while 0<=i<n and 0<=j<n:
                ss = s[i: j+1]
                if ss == ss[::-1]:
                    if len(ss) > len(res):
                        res = ss
                    i -= 1
                    j += 1
                else:
                    break

        for i in range(n):
            find(i, i)
            find(i, i+1)
        return res', N'Python On2 solution - very simple.', 140, 5, 7);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (214, N'class Solution:
