INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (220, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        start, extent = 0, 1
        for i in range(len(s) - 1):
            possLen = 2 * min(i + 1, len(s) - i)
            if i >= len(s) // 2 and extent > possLen:
                break
            if possLen > extent:
                j, jEnd = 0, min(len(s) - i - 1, i + 1)
                while j < jEnd and s[i + j + 1] == s[i - j]:
                    j += 1
                if 2 * j > extent:
                    start, extent = i - j + 1, 2 * j
                if possLen - 1 > extent:
                    j, jEnd = 1, min(len(s) - i, i + 1)
                    while j < jEnd and s[i + j] == s[i - j]:
                        j += 1
                    if 2 * j - 1 > extent:
                        start, extent = i - j + 1, 2 * j - 1
        return s[start:start + extent]', N'Counting Ripples in a Pond', 298, 5, 5);
