INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (227, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        
# edge cases: for a char or less return str        
# 2 pointers, from beginning and end
# if they == append to another list.        
        N = len(s)
        if N <= 1: 
            return s
            
        N = 2*N+1    # Position count
        L = [0] * N
        L[0] = 0
        L[1] = 1
        C = 1     # centerPosition
        R = 2     # centerRightPosition
        i = 0    # currentRightPosition
        iMirror = 0     # currentLeftPosition
        maxLPSLength = 0
        maxLPSCenterPosition = 0
        start = -1
        end = -1
        diff = -1

        for i in range(2,N):
      
            # get currentLeftPosition iMirror for currentRightPosition i
            iMirror = 2*C-i
            L[i] = 0
            diff = R - i
            # If currentRightPosition i is within centerRightPosition R
            if diff > 0:
                L[i] = min(L[iMirror], diff)
    
            # Attempt to expand palindrome centered at currentRightPosition i
            # Here for odd positions, we compare characters and
            # if match then increment LPS Length by ONE
            # If even position, we just increment LPS by ONE without
            # any character comparison
            try:
                while ((i+L[i]) < N and (i-L[i]) > 0) and \
                        (((i+L[i]+1) % 2 == 0) or \
                        (s[(i+L[i]+1)//2] == s[(i-L[i]-1)//2])):
                    L[i]+=1
            except Exception as e:
                pass
    
            if L[i] > maxLPSLength:        # Track maxLPSLength
                maxLPSLength = L[i]
                maxLPSCenterPosition = i
            
            if i + L[i] > R:
                C = i
                R = i + L[i]
    
        start = (maxLPSCenterPosition - maxLPSLength) // 2
        end = start + maxLPSLength - 1
        
        return s[start:end+1]', N'Python O(n) 95% faster O(n) Solution', 350, 5, 11);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (228, N'class Solution:
    def longestPalindrome(self, A: str) -> str:
        
        n = len(A)
        res = ""    # for storing longest palindrome
        resLen = 0  # for storing length of longest palindrome
        for i in range(0 , n):
            
            # for odd length palindrome check
            l , r = i, i

            while (l >=0 and r < n and A[l] == A[r]):
                if (r - l + 1) > resLen:
                    resLen = (r - l + 1)
                    res = A[l : r+1]
                # decrement l and increment r and check if we can get palindrome of larger size
                l -= 1
                r += 1

            # for even length palindrome
            l , r = i , i + 1

            while (l >= 0 and r < n and A[l] == A[r]):
                if (r - l + 1) > resLen:
                    resLen = (r - l + 1)
                    res = A[l : r+1]
                
                # decrement l and increment r and check if we can get palindrome of larger size
                l -= 1
                r += 1
        return res', N'Python3 | O(N2) | Easy To Understand', 462, 5, 2);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (229, N'class Solution:
