            l, r = i, i
            while l >= 0 and r < len(s) and s[l] == s[r]:
                if (r-l+1)>resLen:
                    res = s[l:r+1]
                    resLen = r-l+1
                l-=1
                r+=1
                
            # even cases
            l, r = i, i+1
            while l >= 0 and r < len(s) and s[l] == s[r]:
                if (r-l+1 )> resLen:
                    res = s[l:r+1]
                    resLen = r-l+1

                l-=1
                r+=1
        return res', N'Simple Python Solution', 640, 5, 18);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (230, N'class Solution:
    def longestPalindrome(self, s: str) -> str:
        self.res = "";
        self.resLen = 0;
        for i in range(len(s)):
            self.getPalindrome(s,i,i);
            self.getPalindrome(s,i,i+1);
        return self.res;
    def getPalindrome(self,s,l,r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            if (r - l + 1) > self.resLen:
                self.res = s[l:r+1];
                self.resLen = len(self.res);
            l -= 1;
            r += 1;', N'Palindromic Subtring (Best 90% by Memory)', 276, 5, 13);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (231, N'class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1:
