INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (247, N'class Solution:
    def convert(self, s: str, numRows: int) -> str:
        n = 2 * numRows - 2

        if n == 0:
            return s

        ans = s[::n]
        for i in range(1, n//2):
            x, y = s[i::n], s[n-i::n]
            tmp = [None] *len(x+y)
            tmp[::2] = x
            tmp[1::2] = y 
            ans += "".join(tmp)
        ans += s[n//2::n]

        return ans', N'Python implementation with Slice', 357, 6, 4);
