INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (253, N'class Solution:
    def convert(self, s: str, numRows: int) -> str:
        
        # If there is only one row, save time and return the string itself
        if numRows == 1:
            return s
        
        # Create an empty list containing lists, these represent each row
        result = []
        for x in range(numRows):
            result.append([])
            
        # Using two variables ''direction'' and ''ptr'', the current row will be tracked
        # along with which row to add the next variable in. direction = 1 represents down. 
        # direction = 0 represents up
        direction = 0 
        ptr = 0
        
        for ch in s:
            # If its the first row (ptr = 0), we can only move downwards
            if ptr == 0:
                result[ptr].append(ch)
                ptr += 1
                direction = 1
                continue
            # If its the last row (ptr = numRows - 1), we can only move upwards
            if ptr == numRows - 1:
                result[numRows - 1].append(ch)
                ptr -= 1
                direction = 0
                continue
            # Append and increase/decrease ptr based on direction
            if direction == 1:
                result[ptr].append(ch)
                ptr += 1
            else:
                result[ptr].append(ch)
                ptr -= 1
        
        # Combine all the lists within the list to get the final string
        final = ''''
        for x in result:
            for c in x:
                final += c
        return final', N'Simple Python Solution with Explanation | Beginner Friendly (Beats 90%)', 241, 6, 9);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (254, N'class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1:
            return s
        #distance between characters for the top row
        d0 = 2*numRows - 2
        s_res = ''''
        d = 0 #it will store a variable distance for subsequent rows, except top and bottom ones
        #read 1st row
        while d < len(s):
            s_res += s[d]
            d += d0
        #read subsequent rows
        for i in range(1, numRows-1):
            d = i
            cnt = 2*i
            while d < len(s):
                s_res += s[d]
                d += d0 - cnt #calc new variable distance
                cnt = d0 - cnt #update the variation
        #read nth row
        d = numRows - 1
        while d < len(s):
            s_res += s[d]
            d += d0
        return s_res', N'O(N) implementation using a pattern', 565, 6, 4);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (255, N'class Solution:
