INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (257, N'class Solution:
    def convert(self, s: str, numRows: int) -> str:
        newstr = ""
        if numRows == 1: #one row -> thats just the input string
            return s

        #first row
        j = 0
        while j < len(s):
            newstr += s[j]
            j += 2 * (numRows - 1)

        #middle rows
        for i in range(1, numRows - 1): #i is the row we are constructing
            down = True #we start by going down the zigzag
            j = i
            while j < len(s):
                newstr += s[j]
                if down: #count letters in the rows below
                    toadd = 2 * (numRows - (i + 1))
                else: #count letters in the rows above
                    #amount of rows above = row index
                    toadd = 2 * i
                down = not down #reverse direction
                j += toadd

        #last row
        j = numRows - 1
        while j < len(s):
            newstr += s[j]
            j += 2 * (numRows - 1)

        return newstr', N'Basic Python solution - easy explanation', 463, 6, 7);
