INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (262, N'class Solution:
    def convert(self, s: str, numRows: int) -> str:
        track = ["" for _ in range(numRows)]
        period = numRows + max(0, numRows-2)
        for index, char in enumerate(s):
            rest = index%period
            row = rest if rest<numRows else numRows-(rest-numRows)-2
