INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (310, N'class Solution:
    def reverse(self, x: int) -> int:
        
        result = 0
        limit = 2147483647 if x>=0 else -2147483648
        sign = 1 if x>=0 else -1

        for i, s in enumerate(str(abs(x))):
            if x > 0:
                if result+int(s)*pow(10, i) > limit:
                    return 0
                
            elif x < 0:
                if result-int(s)*pow(10, i) < limit:
                    return 0
            
			# Addition is guaranteed to be in the range: [-2147483648,  2147483647]
            result = result + sign*int(s)*pow(10, i)
            
        return result', N'Python3 solution satisfies 32-bit signed integer condition', 450, 7, 768);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (311, N'class Solution:
    def reverse(self, x: int) -> int:
        # store and take out negation if present
        sign = -1 if x<0 else 1
        x = abs(x)
        
        rev = 0
        # reverse digit by dividing by 10 
        while x:
            x, mod = divmod(x, 10)
            rev = rev*10 + mod
        
        # check if result is outside the contraint
        if rev >= 2**31-1 or rev <= -2**31:
            return 0
        
        # otherwise return
        return rev*sign', N'python3 solution with comments with for humans', 19, 7, 144);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (312, N'class Solution:
    def reverse(self, x: int) -> int:
        if x < 0:
            # Sign ommited as we do all ops unsigned
            INT_LIMIT_QUOTIENT, INT_LIMIT_REMAINDER= divmod(2**31, 10)
            sign = -1
        else: #positive
            INT_LIMIT_QUOTIENT, INT_LIMIT_REMAINDER= divmod(2**31 - 1, 10)
            sign = 1

        x = x * sign
        reverse = 0
        while x:
            x, digit  = divmod(x, 10)
            if (reverse > INT_LIMIT_QUOTIENT
                or (reverse == INT_LIMIT_QUOTIENT
                    and digit > INT_LIMIT_REMAINDER)):
                return 0
            reverse = reverse * 10 + digit
            
        return sign * reverse', N'Python With Overflow Check During Computation', 622, 7, 448);
