INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (323, N'class Solution:
    def reverse(self, x: int) -> int:
                    
        if (x) == 0:
            return x

        count = 0
        digit_position = 1
        answer = []

        negative = False
        if abs(x) != x:
            negative = True
            x = abs(x)


        #Code basically does this:
        #Number = 531
        # Removes first digit position(1) 1 times and adds "1" to a list
        # Removes second digit position(3) 3 times and adds "3" to a list
        # Removes thidre digit position(5) 5 times  and adds "5" to a list
        # Which means answer = [''1'', ''3'', ''5'']
        # list items are made int and joined
        # If the given number was negative the answer is multiplied by -1

        while x != 0:
            
            while x % (10*digit_position) != 0:

                x -= digit_position
                count += 1*digit_position

            answer.append(str(int((count/digit_position))))
            
            count = 0
            digit_position *= 10

        answer = (''''.join(answer))
        if negative:
            answer = int(answer)* -1
        
        if abs(int(answer)) >= 2147483647:
            return 0
            
        return int(answer)', N'Cool and fast python solution (long)', 395, 7, 1);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (324, N'class Solution:
    def reverse(self, x: int) -> int:
        MININT = -2**31
        MAXINT = 2**31 - 1
        MAXINTD10 = MAXINT // 10

        if x == MININT:
            return 0

        is_negative = x < 0
        if is_negative:
            x = -x

        y = 0
        while x != 0:
            x, r = divmod(x, 10)

            if y > MAXINTD10:
                return 0

            y *= 10
            y += r

        if is_negative:
            y = -y

        return y', N'Simple Solution with Proper Limit Handling, The Best', 240, 7, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (325, N'class Solution:
