INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (332, N'class Solution:
    def myAtoi(self, s: str) -> int:
     
        if not s:
            return 0
        sign = 1
        integer = 0
        i = 0
        while i < len(s) and s[i] == '' '':
            i+=1    #skipping leading white space
        if i < len(s) and (s[i] == ''-'' or s[i] == ''+''):
            if s[i] == ''-'':
                sign = -1
            i+=1
        while(i < len(s) and s[i].isdigit()):
            integer = integer * 10 + int(s[i])
            i+=1
            
        integer = sign*integer
        ans = self.limit(integer)
        return ans
    
    def limit(self, num):
        if num > pow(2, 31) -1:
            return pow(2, 31) -1
        if num < -1*pow(2, 31):
            return -1*pow(2, 31)
        return num', N'Python Simple Solution without Strip beats 95%', 136, 8, 790);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (333, N'class Solution:
    def myAtoi(self, s: str) -> int:
        if not s:
            return 0

        # remove leading and trailing whitespace
        s = s.strip()

        # save sign if one exists
        pos = True
        if s and s[0] == ''-'':
            pos = False
            s = s[1:]
        elif s and s[0] == ''+'':
            s = s[1:]
        
        # ignore leading zeros
        i = 0
        while i < len(s) and s[i] == ''0'':
            i += 1

        # apply relevant digits
        res = None
        while i < len(s) and s[i] in ''0123456789'':
            if res is None:
                res = int(s[i])
            else:
                res = (res * 10) + int(s[i])
            i += 1
        res = 0 if res is None else res

        # apply sign
        res = res if pos else -res

        # clip result
        res = max(res, -2**31)
        res = min(res, (2**31)-1)

        return res', N'Python Very Intuitive with Comments', 355, 8, 1000);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (334, N'class Solution:
    def myAtoi(self, s: str) -> int:
        i = res = 0
        op = 1
        while i < len(s) and s[i] == '' '':
            i += 1
        if i < len(s) and s[i] in ''+-'':
            op = 1 if s[i] == ''+'' else -1
            i += 1
        
        MAX_RES = (1 << 31) - 1 if op == 1 else 1 << 31
        while i < len(s) and s[i].isdigit() and res <= MAX_RES:
            res = res * 10 + int(s[i])
            i += 1
            
        return min(res, MAX_RES) * op', N'[Python3] Not an interesting problem, but here is my O(n) Time | O(1) Space solution', 438, 8, 322);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (335, N'class Solution:
