INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (352, N'class Solution:
    def myAtoi(self, s: str) -> int:
        length = len(s)
        if length == 0: 
            return 0

        res = ""
        sign = 1
        i = 0

        # skip all of the whitespaces
        while s[i] == '' '':
            i += 1
            if i >= length:
                return 0

        # get the sign 
        if s[i] == ''-'':
            sign = -1
            i += 1
        elif s[i] == ''+'':
            sign = 1
            i += 1
        if i >= length:
            return 0
        
        # if the character after the sign is not a digit, return 0
        if s[i] not in "0123456789":
            return 0

        # otherwise it is a digit and the number can be read
        else:
            while s[i] in "0123456789":
                res += s[i]
                i += 1
                if i >= length:
                    return self.clampResult(int(res) * sign)

        return self.clampResult(int(res) * sign)

    def clampResult(self, res) -> int:
        # clamp the result between -2^31 and 2^31-1
        return max(min(2147483647, res), -2147483648)', N'Easy Python 3 | 95.37% Runtime, 99,3% Memory | With Explanation', 32, 8, 4);
