INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (354, N'class Solution:
    def myAtoi(self, s: str) -> int:
        i, sign, out = 0, 1, ""

        # going pass the leading spaces
        while i < len(s):
            if s[i] == " ":
                i += 1
            else:
                break
        # checking for symbols
        if i < len(s):
            if s[i] == "-": 
                sign = -1
                i += 1
            elif s[i] == "+":
                i += 1
        # checking for digits and adding them to out and stopping completely if no digit is encountered
        while i < len(s) and s[i].isdigit():
            out += s[i]
            i += 1
        # checking if any digit has been read 
        if out == "":
            return 0
        # formalitites
        else:
            out =  sign * int(out)
            if out < -(2 ** 31):
                out = - (2 ** 31)
            elif out > (2 ** 31) - 1:
                out = (2 ** 31) - 1
            return out', N'Python simple solution | Beats 92% in time, 79 % in space', 244, 8, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (355, N'class Solution:
    def myAtoi(self, s: str) -> int:
