INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (358, N'class Solution:
    def myAtoi(self, s: str) -> int:
        s = s.strip('' '')
        positive, s = self.PositiveNumber(s)
        num = self.StringToNum(s)
        if not positive:
            num = num * -1
        num = self.CheckNumBoundries(num)
        return num

    @staticmethod
    def PositiveNumber(s:str) -> tuple[bool, str]:
        if s and s[0] == ''-'':
            return False, s[1:]
        if s and s[0] == ''+'':
            return True, s[1:]
        return True, s

    @staticmethod
    def StringToNum(s: str) -> int:
        hit_non_zero = False
        tmp = ''''
        for num in s:
            if not hit_non_zero and num == ''0'':
                continue
            hit_non_zero = True
            try:
                int(num)
            except ValueError:
                break
            tmp += num
        if not tmp:
            return 0
        return int(tmp)

    @staticmethod
    def CheckNumBoundries(num):
        if (n:=(2**31 -1)) < num:
            return n
        if (n:=(-2**31)) > num:
            return n
        return num', N'Stuff', 259, 8, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (359, N'class Solution:
    def myAtoi(self, s: str) -> int:
