            if num > 2 **31 - 1:
                num = 2 **31 - 1
            elif num < - 2 **31:
                num = - 2 **31
            return num        
        
        def plusminus(num: int, Flag: bool) ->int:
            if Flag == False:
                return -num
            else:
                return num
            
        flag = True
        Num = 0
        sin = s.strip()
        if sin == '''':
            return 0

        if sin[0].isdigit() or sin[0] == ''+'' or sin[0] == ''-'':
            if sin[0] ==''-'':
                flag = False
                sin = sin[1:len(sin)]
            elif sin[0] ==''+'':
                flag = True
                sin = sin[1:len(sin)]
        else:
            return 0

        for i in range(0, len(sin)):
            if sin[i].isdigit():
                Num = Num * 10  + int(sin[i])
                i += 1
            else:
                break
        res = plusminus(Num, flag)
        return clamp(res)', N'[Python3] 81.62 % runtime beats & 78.94 % memory beats solution.', 449, 8, 9);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (360, N'class Solution:
	def myAtoi(self, s: str) -> int:
		n = len(s)
		nums = set()
		for i in range(10):
			nums.add(str(i))

		sign, i = 1, 0
		while i < n and s[i] == '' '': i += 1 
		if i<n and s[i] == ''-'': 
			sign = -sign
			i += 1
		elif i< n and s[i] == ''+'': i += 1

		digits = []
		while i < n and s[i] in nums: 
			digits.append(int(s[i]))
			i += 1

		m, num = len(digits), 0

		for i,v in enumerate(digits):
			if sign == -1: num -= v*(10**(m-i-1))
			else: num += v*(10**(m-i-1))
			if num <= -2**31: return -(2**31)
			if num >= 2**31 - 1: return 2**31 - 1

		return num', N'Python || Straight Forward', 532, 8, 19);
