INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (365, N'class Solution:
    def myAtoi(self, s: str) -> int:
        final = []
        digits_reached = False
        r = [-2**31, 2**31 - 1]

        #  ignore any leading whitespace
        s = s.lstrip()
        
        #  check if next character is - or + (if not at the end of string)
        #  [this affects the final result]
        if len(s) > 0:
            if s[0] == "+" or s[0] == "-":
                final.append(s[0])

        if len(final) == 0:
            s = s
        else:
            s = s[1:]

        #  read in the next characters until the non-digit char / end of the input is reached.
        for i in range(len(s)):
            val = s[i]
            if val.isdigit():
                final.append(val)
                digits_reached = True
            else:
                break
        
       #  if no digits is reached, then the integer is 0
        if digits_reached is False:
            return 0
        # should be in the integer range [-2**31, 2**31 - 1]
        else:
            final = int("".join(final))
            if final < r[0]:
                return r[0]
            elif final > r[1]:
                return r[1]
            else:
                return final', N'Ekomobong Archibong Solution??', 640, 8, 2);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (366, N'class Solution:
    def myAtoi(self, s: str) -> int:
        # First get rid of any leading or trailing spaces in the string. Initiate an empty final answer list
