INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (377, N'class Solution:
    def myAtoi(self, s: str) -> int:
        sign = None
        number = "0" # if no integer were read, the integer is 0
        i, l = 0, len(s)
        
		# Max  and min ints
        MAX = 2**31 - 1
        MIN = -2**31
        
        
        # Algorithm from description
        # 1. Read and ignore any leading whitespace
        while i < l and s[i] == '' '':
            i += 1
        
        # 2. Check if the next character is - or +
		# If the sign is None we assign it but the following character is a sign, we want to return 0 (case: "+-12")
        if i < l and s[i] == ''+'':
            if not sign:
                sign = 1
                i += 1
            else:
                return 0
            
        if i < l and s[i] == ''-'':
            if not sign:
                sign = -1
                i += 1
            else:
                return 0
            
        # 3. Read the next characters as long as it is an int
        while i < l and s[i].isdigit():
            number += s[i]
            i += 1
        
        # If no sign symbol was given. Assume positive sign
        if not sign:
            sign = 1
		
        # 4. Convert into integer with the correct sign
        number = int(number) * sign
        
        # 5. If the integer is out of range, clamp it
        number = min(number, MAX)
        number = max(number, MIN)
        
        # 6. Return
        return number', N'Simple Python Walk', 547, 8, 30);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (378, N'class Solution:
