                ans+=i
                break
            elif len(i)==1 and (i==''0'' or i==''1'' or i==''2'' or i==''3'' or\
                    i==''4'' or i==''5'' or i==''6'' or i==''7'' or\
                    i==''8'' or i==''9''):
                ans+=i
                break
            else:
                for j in range(0, len(i)):
                    if i[j]==''+'' and j==0:
                        ans+=i[j]
                    elif i[j]==''-'' and j==0:
                        ans+=i[j]
                    elif i[j]==''0'' or i[j]==''1'' or i[j]==''2'' or i[j]==''3'' or\
                    i[j]==''4'' or i[j]==''5'' or i[j]==''6'' or i[j]==''7'' or\
                    i[j]==''8'' or i[j]==''9'':
                        ans+=i[j]
                    else:
                        break
            break
        if len(ans)==0:
            return 0
        elif len(ans)==1:
            if ans[0]==''+'' or ans[0]==''-'': return 0
            return int(ans)
        else:
            if ans[0]==''+'':
                v=int(ans[1:])
            elif ans[0]==''-'':
                v=-1*int(ans[1:])
            else:
                v=int(ans)
            if v<-1*(2**31):
                return -1*(2**31)
            elif v>(2**31-1):
                return 2**31-1
            return v', N'Simple || EZ || beats ~94 %', 13, 8, 27);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (382, N'class Solution:
    def myAtoi(self, s: str) -> int:
        s= s.strip(" ")
        if len(s) == 0:return 0
        s = list(s)
        sign = 1
        
        if s[0] == "-":
            sign = -1
            s.pop(0) # Removing the sign from the first term 
        elif s[0] == "+":
            sign = 1
            s.pop(0)
        else:
            pass
        
        if len(s) > 2 and not s[0].isdigit():
            return 0
        _ = "0"
        
        for i in s:
            if i.isdigit():
                _+=i
            else:
                break
                
        return_val = int(_) * sign
        
        if return_val < -2147483648:
            return -2147483648
        
        elif return_val > 2147483647:
            return 2147483647
        
        else:
            return return_val', N'Beats 99% of memory use', 47, 8, 98);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (383, N'class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x < 0:
            return False
        
        res = 0
        temp = x
        
        while temp:
            temp, n = divmod(temp, 10)
            res = (res * 10) + n
                
        return res == x', N'Easy Python Solution with O(1) space', 335, 9, 1900);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (384, N'class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x < 0:
            return False
        length, temp = -1, x
        while temp:
            temp = temp // 10
            length += 1
        
        temp = x
        while temp:
            left, right = temp // 10**length, temp % 10
            if left != right:
                return False
            temp = (temp % 10**length) // 10
            length -= 2
        return True', N'Palindrome Number | Python solution without String or Reverse', 177, 9, 442);
