INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (397, N'class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x<0:
            return False
        if x<10:
            return True
        i = 10
        start = 0
        lst = []
        while i >= 0:
            digit = x//(10**i)
            if digit == 0 and start == 0:
                i -= 1
                continue
            else:
                if start == 0:
                    n = i
                start = 1
                lst.append(digit)
                x-= digit*(10**i)
                i -= 1
        i, j = 0, n
        while i<=j:
            if lst[i] == lst[j]:
                i += 1
                j -= 1
                continue
            else:
                return False
        return True', N'Solution without converting integer to string', 290, 9, 174);
