INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (426, N'class Solution:
   def isMatch(self, s, p):
       n = len(s)
       m = len(p)
       dp = [[False for _ in range (m+1)] for _ in range (n+1)]
       dp[0][0] = True
       for c in range(1,m+1):
           if p[c-1] == ''*'' and c > 1:
               dp[0][c] = dp[0][c-2]
       for r in range(1,n+1):
           for c in range(1,m+1):
               if p[c-1] == s[r-1] or p[c-1] == ''.'':
                   dp[r][c] = dp[r-1][c-1]
               elif c > 1 and p[c-1] == ''*'':
                   if  p[c-2] ==''.'' or s[r-1]==p[c-2]:
                       dp[r][c] =dp[r][c-2] or dp[r-1][c]
                   else:
                       dp[r][c] = dp[r][c-2]
       return dp[n][m]', N'[Fastest Solution Explained][0ms][100%] O(n)time complexity O(n)space complexity', 478, 10, 1300);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (427, N'class Solution:
    def isMatch(self, s, p):
        n = len(s)
        m = len(p)
        dp = [[False for _ in range (m+1)] for _ in range (n+1)]
        dp[0][0] = True
        for c in range(1,m+1):
            if p[c-1] == ''*'' and c > 1:
                dp[0][c] = dp[0][c-2]
        for r in range(1,n+1):
            for c in range(1,m+1):
                if p[c-1] == s[r-1] or p[c-1] == ''.'':
                    dp[r][c] = dp[r-1][c-1]
                elif c > 1 and p[c-1] == ''*'':
                    if  p[c-2] ==''.'' or s[r-1]==p[c-2]:
                        dp[r][c] =dp[r][c-2] or dp[r-1][c]
                    else:
                        dp[r][c] = dp[r][c-2]
        return dp[n][m]', N'[Python3]dynamic programming', 553, 10, 1000);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (428, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        n_s=len(s)
        n_p=len(p)
        dp=[[False]*(n_p+1) for _ in range(n_s+1)]
        dp[0][0]=True
        
        
        #For empty string but the "*" in pattern might return True
        for i in range(1,n_p+1):
            if p[i-1]=="*":
                dp[0][i]=dp[0][i-2]
        
        for i in range(1,n_s+1):
            for j in range(1,n_p+1):
                #When the character in string matches with the patter or the pattern has ''.'', which accepts any character
                if s[i-1]==p[j-1] or p[j-1]==''.'':
                    dp[i][j]=dp[i-1][j-1]
                #When the pattern has "*", this shows that we need to check the [j-2] for the character, which can be the string character or ''.''. In this case we will check the [i-1][j], to check if the character except the current one is True.
                
                elif p[j-1]=="*":
                    dp[i][j]=dp[i][j-2]
                    if p[j-2]==''.'' or p[j-2]==s[i-1]:
                        dp[i][j]=dp[i][j] or dp[i-1][j]
                    
            
        return dp[n_s][n_p]', N'Dynamic programming | Python', 527, 10, 343);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (429, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        
        dp = {}
        def dfs(i,j):
            if (i,j) in dp:
                return dp[(i,j)]
            
            if i>=len(s) and j>=len(p):
                return True
            if i<= len(s) and j>= len(p):
                return False
            match  =  i< len(s) and ((s[i] == p[j]) or (p[j] == ''.''))
            
            if j < len(p)-1 and  p[j+1] == ''*'':
                dp[(i,j)] = ( dfs(i,j+2) # dont use *  
                    or (match and dfs(i+1,j)) )
                return dp[(i,j)]
            if match:
                dp[(i,j)] = dfs(i+1,j+1) 
                return dp[(i,j)]
        
        return dfs(0,0)', N'Python 95% faster', 448, 10, 446);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (430, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p)
        
        @lru_cache(None)
        def helper(i, j):
            if j == n:
                return i == m
            
            match = i != m and (p[j] == ''.'' or s[i] == p[j])
            if j == n - 1 or p[j + 1] != ''*'':
                return match and helper(i + 1, j + 1)
            
            return helper(i, j + 2) or (match and helper(i + 1, j))
        
        return helper(0, 0)', N'python 3 | memoization', 454, 10, 287);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (431, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        # when pattern(p) is "", check with string(s)
        if not p:
            return s == p
        # when the last char of pattern(p) is *
        if p[-1] == "*":
            # *=0,the char before * is repeated 0 times
            if self.isMatch(s, p[: -2]):
                return True
            
            # when string(s) is "" and pattern(p) has chars
            if not s:
                return False
            
            # delete once repeated times
            if p[-2] == "." or p[-2] == s[-1]:
                return self.isMatch(s[: -1], p)

        # when string(s) is "" and pattern(p) has chars
        if not s:
            return False

        # delete last repeated cher
        if p[-1] == "." or p[-1] == s[-1]:
            return self.isMatch(s[: -1], p[: -1])', N'python3 can I use regex?', 572, 10, 123);
