        return s and (p[-1] == s[-1] or p[-1] == ''.'') and self.isMatch(s[:-1], p[:-1])', N'Could this be the shortest and fastest Python Solution?', 520, 10, 409);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (433, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        while not (s=='''' and p==''''):
            if len(p) >= 2:
                if p[:2] == ''.*'':
                    for m in range(len(s)+1):
                        if self.isMatch(s[m:], p[2:]):
                            return True
                    return False
                elif p[1] == ''*'':
                    for m in range(len(s)+1):
                        if s[:m] != p[0] * m:
                            return False
                        if self.isMatch(s[m:], p[2:]):
                            return True
                    return False

            if s == '''' or p == '''':
                return False

            if p[0].isalnum():
                if p[0] != s[0]:
                    return False
            elif p[0] == ''.'':
                pass
            else:
                return False

            p = p[1:]
            s = s[1:]

        else:
            return True', N'Straightforward recursive solution in Python', 86, 10, 4);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (434, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        def helper(s, p):
            for i, j in zip(s, p):
                if j != "." and i != j:
                    return False
            return True if len(s) == len(p) else False
       
        def starc(s, p, x=0, y=0):
            key = y
            while x < len(p) and y < len(s):
                if len(p[x]) == 2:
                    if s[y] == p[x][0] or p[x][0] == ".":
                        y += 1
                    elif s[y] != p[x][0]:
                        x += 1
                else:
                    break
            return True if y - key == len(s) else False
        if "*" in p:
            memo = []
            cut = ""
            for x in range(len(p)):
                if p[x] == "*":
                    if any(cut[:-1]):
                        memo.append([cut[:-1]])
                    memo.append(cut[-1]+"*")
                    cut = ""
                elif p[x] != "*":
                    cut = cut + p[x]
            if any(cut): memo.append([cut])

            for i in range(len(memo)):
                if type(memo[i]) == list:
                    y = 0
                    for v in memo:
                        if type(v) == list:
                            if len(v) > 1:
                                y = v[1] + len(v[0])
                    g = sum((len(x[0]) for x in memo[i + 1:] if type(x) == list))
                    while y + len(memo[i][0]) <= len(s) - g:
                        if helper(s[y: y + len(memo[i][0])], memo[i][0]):
                            memo[i] = memo[i] + [y]
                        y += 1
                    if len(memo[i]) == 1:
                        return False
             
            if not any([x for x in memo if type(x)==list and len(x)>1]):
                return starc(s,memo)
            must = [x for x in range(len(memo)) if type(memo[x])==list]
            place = []
            for z in must:
               if not any(place):
                    for i in memo[z][1:]:
                        place.append([i])
               else:
                    cut = len(place)
                    for k in range(len(place)):
                        a = place[k]
                        for i in memo[z][1:]:
                            place.append(a+[i])
                    place = place[cut:]
            for cp in place:
                if len(set(cp)) != len(cp):
                    continue
                d = 0
                s2 = s
                howcut = []
                while d < len(cp):
                    if d < len(cp)-1:
                        if cp[d] + len(memo[must[d]][0]) > cp[d+1]: break
                        back = []
                        for e in memo[:must[d]][::-1]:
                            if type(e) == str:
                                back.append(e)
                            else:
                                break
                        cc = 0
                        if any(howcut):
                            cc = sum(howcut)
                        if starc(s2[:cp[d]-cc], back[::-1]):
                            howcut.append(len(s2[:cp[d]-cc + len(memo[must[d]][0])]))
                            s2 = s2[(cp[d]-cc) + len(memo[must[d]][0]):]
                            if any(s2):
                                d += 1
                                continue
                            else:
                                break
                        else:
                            break    
                    elif d == len(cp) -1:
                        back = []
                        for e in memo[:must[d]][::-1]:
                            if type(e) == str:
                                back.append(e)
                            else:
                                break
                        cc = 0
                        if any(howcut):
                            cc = sum(howcut)
                        if starc(s2[:cp[d]-cc], back[::-1]):
                            howcut.append(len(s2[:cp[d]-cc + len(memo[must[d]][0])]))
                            s2 = s2[(cp[d]-cc) + len(memo[must[d]][0]):]
                            front = []
                            for e in memo[must[d]+1:]:
                                if type(e) == str:
                                    front.append(e)
                                else:
                                    break
                            if starc(s2, front):
                                return True
                            else:
                                break
                        else:
                            break
            return False
        else:
            return helper(s,p)', N'PYTHON 3 Part by Part Explained Solution beginner friendly :)', 551, 10, 6);
