INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (438, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        n, m = len(s), len(p)
        t = [[-1 for _ in range(n+1)] for _ in range(m+1)]
        t[0][0] = True
        
        for j in range(1, n+1):
            t[0][j] = False
        
        for i in range(1, m+1):
            if p[i-1] == ''*'':
                t[i][0] = t[i-2][0]
            else:
                t[i][0] = False
        
        for i in range(1, m+1):
            for j in range(1, n+1):
                if p[i-1].isalpha():
                    if p[i-1] == s[j-1]:
                        t[i][j] = t[i-1][j-1]
                    else:
                        t[i][j] = False
                elif p[i-1] == ''.'':
                    t[i][j] = t[i-1][j-1]
                elif p[i-1] == ''*'':
                    if p[i-2] == s[j-1] or p[i-2] == ''.'':
                        t[i][j] = t[i-2][j] or t[i][j-1]
                    else:
                        t[i][j] = t[i-2][j]
        
        return t[m][n]', N'Python easy to read and understand | DP', 71, 10, 267);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (439, N'class ParserNode:
    def __init__(self, nxt=None):
        self.nxt = nxt
        
    def __str__(self): pass
    
    #using "generator" since a ParserNode may consume a variety of combinations from p, 
    #this is basic form
    def genparse(self, s):
        if s and self.match(s[0]):
            yield s[1:]
            
    def parsealong(self, s):
        #print(self, s)
        for s_ in self.genparse(s):
            #success: s is consumed (s_ == []) and no nxt
            if not s_ and not self.nxt:
                return True
            
            #success: any downstream ParserNodes find success
            if self.nxt and self.nxt.parsealong(s_):
                return True
                
        return False

    
####################################


class DotParserNode(ParserNode):
    def __str__(self):
        return f"DotParserNode => {self.nxt}"
    
    def match(self, ch):
        return True
            

####################################


class CharParserNode(ParserNode):
    def __init__(self, ch):
        ParserNode.__init__(self)
        self.ch = ch
        
    def __str__(self):
        return f"CharParserNode({self.ch}) => {self.nxt}"
        
    def match(self, ch):
        return self.ch == ch

    
####################################
    
    
class StarParserNode(ParserNode):
    def __init__(self, prev):
        ParserNode.__init__(self)
        self.prev = prev
        
    def __str__(self):
        return f"StarParserNode({self.prev}) => {self.nxt}"
        
    def match(self, ch):
        if self.prev:
            return self.prev.match(ch)
        return False
    
    def genparse(self, s):
        #0
        yield s
                    
        #1+
        if s:
            for i in range(len(s)):
                if self.match(s[i]):
                    yield s[i+1:]
                else:
                    break

                    
####################################

    
class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        
        p = list(p)
        
        #helper function to get parserNode from current, next character pairs
        def parserNodeFactory(c, n):
            if n == ''*'':
                return StarParserNode(parserNodeFactory(c, None))
            if c == ''*'':
                return None
            if c == ''.'':
                return DotParserNode()
            return CharParserNode(c)
        
        #build linked list of ParserNodes from p
        head, tail = None, None
        
        if len(p) == 1:
            head = parserNodeFactory(p[0], None)
            
        else:
            itr = zip(p, p[1:] + [None])
            head = parserNodeFactory(*next(itr))
            tail = head
            for c, n in itr:
                node = parserNodeFactory(c, n)
                if node:
                    tail.nxt = node
                    tail = tail.nxt
            
        return head.parsealong(s)
        
####################################', N'python3, linked list of sub-parsers. Object-oriented with inheritance', 263, 10, 56);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (440, N'class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        arr = []
        i = 0
        while i < len(p):
            if i+1 < len(p) and p[i+1] == ''*'':
                arr.append(p[i]+''*'')
                i+=2
            else:
                arr.append(p[i])
                i += 1
        verified = set([-1])
        def verify(idx, op,s):
            ans = set()
            if idx <= len(s):
                if ''*'' not in op and idx < len(s) and (s[idx] == op or op == ''.''):
                    ans.add(idx)
                elif ''*'' in op:
                        ans.add(idx-1)
                        for i in range(idx,len(s)):
                            if op[0] == ''.'' or s[i] == op[0]:
                                ans.add(i)
                            else:
                                break
            return ans
                    
        for vLevel in range(len(arr)):
            newVerified = set()
            for v in verified:
                newVerified |= verify(v+1,arr[vLevel],s)
            verified = newVerified
        return len(s)-1 in verified', N'Python3 Solution beats 90%: Sequential Verification', 110, 10, 127);
