INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (479, N'class Solution:
    def maxArea(self, height: List[int]) -> int:
       
        # Init 
        area = -inf
        i = 0
        j = len(height)-1
        
        # Two pointer solution
        while i < j:
            
            # Calc breath
            breath = j-i
            
            # Keep track of max length
            if height[i] < height[j]:
                length = height[i]
                i += 1
            else:
