INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (482, N'class Solution:
    def maxArea(self, h: List[int]) -> int:
        
        # Maximum Volume
        m = 0
        
        # Left Index
        l = 0
        
        # Right Index
        r = len(h) - 1

        while l != r:
            
            # Volume is height of lowest wall times distance between walls
            v = min(h[l], h[r]) * (r - l)
            
            # If volume is bigger than current maximum, save new max
            if v > m:
                m = v
                
            # Keep highest wall and move the other end towards it
            if h[l] > h[r]:
                r -= 1
            else:
                l += 1

        return m', N'Python 3 commented', 11, 11, 96);
