        dic={1:''I'',5:''V'',10:''X'',50:''L'',100:''C'',500:''D'',1000:''M''}
        s=""
        while num!=0:
            y=num%pow(10,i)//pow(10,i-1)
            if y==5:
                s=dic[y*pow(10,i-1)]+s
            elif y==1:
                s=dic[y*pow(10,i-1)]+s
            elif y==4:
                s=dic[1*pow(10,i-1)]+dic[5*pow(10,i-1)]+s
            elif y==9:
                s=dic[1*pow(10,i-1)]+dic[1*pow(10,i)]+s
            elif y<4:
                s=dic[pow(10,i-1)]*y+s
            elif y>5 and y<9:
                y-=5
                s=dic[5*pow(10,i-1)]+dic[pow(10,i-1)]*y+s
            num=num//pow(10,i)
            num*=pow(10,i)
            i+=1
        return s', N'Fastest Python solution using mapping', 209, 12, 2400);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (499, N'class Solution:
    def intToRoman(self, num: int) -> str:
        dct = {1: ''I'', 4: ''IV'', 5: ''V'', 9: ''IX'', 10: ''X'', 40: ''XL'', 50: ''L'', 90: ''XC'', 100: ''C'', 400: ''CD'', 500: ''D'', 900: ''CM'', 1000: ''M''}
        stack = [1, 4, 5, 9, 10, 40, 50, 90, 100, 400, 500, 900, 1000]
        ans = []
        while num > 0:
            if stack[-1] > num:
                stack.pop()
            else:
                num -= stack[-1]
                ans.append(dct[stack[-1]])
        return "".join(map(str, ans))', N'Python Stack Solution', 601, 12, 1000);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (500, N'class Solution:
