INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (508, N'class Solution:
	def intToRoman(self, num: int) -> str:
		rome = { 1: ''I'', 5: ''V'', 4: ''IV'', 10: ''X'', 9: ''IX'', 50: ''L'', 40: ''XL'', 100: ''C'', 90: ''XC'', 500: ''D'', 400: ''CD'', 1000: ''M'', 900: ''CM'' }

		R = ''''
