INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (515, N'class Solution:
    def intToRoman(self, num: int) -> str:  # Time: O(n) and Space: O(1)
        symbolList = [[''I'', 1], [''IV'', 4], [''V'', 5], [''IX'', 9], 
                      [''X'', 10], [''XL'', 40], [''L'', 50], [''XC'', 90],
                      [''C'', 100], [''CD'', 400], [''D'', 500], [''CM'', 900], 
                      [''M'', 1000]]
        res = ''''
		
        for symbol, val in reversed(symbolList):  # we will traverse the list in reverse order
            if num // val:                        # num//val = 0 means False, else True
                count = num // val
                res += (symbol * count)
                num = num % val
				
        return res  # After iterating through all the symbols in the list', N'Python beats 90% with full working explanation', 28, 12, 244);
