INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (518, N'class Solution:
    def intToRoman(self, num: int) -> str:
        letters = {1: ''I'', 5: ''V'', 10: ''X'', 50: ''L'', 100: ''C'', 500: ''D'', 1000: ''M''}
        i = 1
        roman=""
        while num != 0:
            digit = num % 10
            if digit==1 or digit==5:
                roman=letters[digit*i]+roman
            elif digit==2 or digit==3:
                roman=(letters[1*i] * digit) + roman
            elif digit==4 or digit==9:
                roman=letters[1*i]+letters[(digit+1)*i] + roman
            elif digit==6 or digit==7 or digit==8:
                roman=letters[5*i]+(letters[1*i] * (digit % 5)) + roman
            num = num // 10
            i*=10
        return roman', N'Python3 98% faster 84% memory', 174, 12, 121);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (519, N'class Solution:
