                s+="D"
            elif(hundreds==9):
                s+="CM"
            elif(hundreds==4):
                s+="CD"
            elif(hundreds>5):
                s+="D"
                s+="C"*(hundreds-5)
            else:
                s+="C"*hundreds
            nums-=100*hundreds
        tens=nums//10
        if(tens>0):
            if(tens==5):
                s+="L"
            elif(tens==9):
                s+="XC"
            elif(tens==4):
                s+="XL"
            elif(tens>5):
                s+="L"
                s+="X"*(tens-5)
            else:
                s+="X"*tens
            nums-=10*tens
        ones=nums
        if(ones>0):
            if(ones==5):
                s+="V"
            elif(ones==9):
                s+="IX"
            elif(ones==4):
                s+="IV"
            elif(ones>5):
                s+="V"
                s+="I"*(ones-5)
            else:
                s+="I"*ones
        return s', N'Simple Python Solution (Beats 100% python3 submission) (16 ms)', 137, 12, 130);
