INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (527, N'class Solution:
    def intToRoman(self, num: int) -> str:
        
        # we''ll maintain the usual mapping but
        # also the "one-less" value mapping. why?
        # because the way we''ve written our solution
        # if we didn''t have the mapping the way we do
        # the output for num=900, would actually be
        # additive i.e. "DCD" rather than "CM"
        rom = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
        dec = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]

        i, res = 0, ""
        
        # loop until we''ve exhausted nums
        while num != 0:
            # now for every curr value
            # of num, check if the current
            # value from the dec array
            # is smaller, if it is, we
            # subtract that value till it''s
            # possible
            # 
            # for e.g. num = 247, we''ll
            # run this loop twice for i=4 (100)
            # and at the same time we''ll add
            # the corresponding roman literal
            # to result i.e "CC" and so on and so forth
            while num >= dec[i]:
                num -= dec[i]
                res += rom[i]
            i += 1
        
        return res', N'[Python] Simple solution explained', 504, 12, 225);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (528, N'class Solution:
    def intToRoman(self, num: int) -> str:
        weights = [
            (1000, ''M''),
            (900, ''CM''),
            (500, ''D''),
            (400, ''CD''),
            (100, ''C''),
            (90, ''XC''),
            (50, ''L''),
            (40, ''XL''),
            (10, ''X''),
            (9, ''IX''),
            (5, ''V''),
            (4, ''IV''),
            (1, ''I'')
        ]

        result = ""
        for weight, weight_symbol in weights:
            if num >= weight:
                qty = (num // weight)
                result += weight_symbol * qty
                num -= qty * weight

        return result', N'Super simple Python solution with runtime: 44 ms, faster than 90.64% submissions', 344, 12, 140);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (529, N'class Solution:
    def intToRoman(self, num: int) -> str:
        rom_dig = ''''
        pre = {0: '''', 1: ''I'', 5:''V'', 10:''X'', 50:''L'', 100:''C'', 500:''D'', 1000:''M''}
        place = 1
        
        while num:
            dig = num%10
            
            if (dig+1)%5==0:
                rom_dig = pre[place]+pre[(dig+1)*place] + rom_dig
            else:
                rom_dig = pre[dig//5*5*place] + dig%5*pre[place] + rom_dig 
                
            num = num//10
            place = place*10
            
        return rom_dig', N'Simple and short python solution (40ms)', 356, 12, 107);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (530, N'class Solution:
    def intToRoman(self, num: int) -> str:
        arr1 = [1,4,5,9,10,40,50,90,100,400,500,900,1000]
        arr2 = [''I'',''IV'',''V'',''IX'',''X'',''XL'',''L'',''XC'',''C'',''CD'',''D'',''CM'',''M'']
        n = num
        i = len(arr1)-1
        st = ''''
        while n != 0 and i>=0:
            if n - arr1[i] >= 0:
                n = n-arr1[i]
                st += arr2[i]
            else:
                i -= 1

        return st', N'Python Greedy solution, easy to understand', 361, 12, 265);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (531, N'class Solution:
    def intToRoman(self, num: int) -> str:
        translator = {1: ''I'', 5: ''V'', 10: ''X'', 50: ''L'', 100: ''C'', 500: ''D'', 1000: ''M'',
                     4: ''IV'', 9: ''IX'', 40: ''XL'', 90: ''XC'', 400: ''CD'', 900: ''CM''}
        
        roman = ''''
        for i in sorted(translator.keys(), reverse=True):
            if num - i >= 0:
                quotient, remainder = divmod(num, i)
                num = remainder
                roman += translator[i] * quotient
        return roman', N'Python Simple O(1)/O(1) Faster Than 87%', 533, 12, 371);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (532, N'class Solution:
    def intToRoman(self, num: int) -> str:
        def romanHelper(upper, middle, lower, factor):
            if factor == 9:
                return lower + upper
            elif factor >= 5:
                return middle + lower*(factor%5)
            elif factor == 4:
                return lower + middle
            else:
                return lower*factor 
        
        roman = ""
        
        if num >= 1000:
            roman += ''M''*(num // 1000)
            num %= 1000
            
        if num >= 100:
            factor = num // 100
            roman += romanHelper(''M'', ''D'', ''C'', factor)
            num %= 100
            
        if num >= 10:
            factor = num // 10
            roman += romanHelper(''C'', ''L'', ''X'', factor)
            num %= 10
            
        roman += romanHelper(''X'', ''V'', ''I'', num)
        
        return roman', N'Faster than 99.64% python solution', 176, 12, 408);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (533, N'class Solution:
    def intToRoman(self, num: int) -> str:
        mp = {1000:"M", 900:"CM", 500:"D", 400:"CD", 100:"C", 90:"XC", 50:"L", 40:"XL", 10:"X", 9:"IX", 5:"V", 4:"IV", 1:"I"}
        ans = []
        for k, v in mp.items(): 
            ans.append(num//k * v)
            num %= k
        return "".join(ans)', N'[Python3] modulo operation', 4, 12, 127);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (534, N'class Solution:
    def intToRoman(self, num: int) -> str:
        mp = {1:"I", 5:"V", 10:"X", 50:"L", 100:"C", 500:"D", 1000:"M"}
        
        ans = []
        m = 1
        while num: 
            num, x = divmod(num, 10)
            if x == 9: ans.append(mp[m] + mp[10*m])
            elif x == 4: ans.append(mp[m] + mp[5*m])
            else: 
                val = ""
                if x >= 5: 
                    val += mp[5*m]
                    x -= 5
                while x: 
                    val += mp[m]
                    x -= 1
                ans.append(val)
            m *= 10
        return "".join(reversed(ans))', N'[Python3] modulo operation', 4, 12, 127);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (535, N'class Solution:
