INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (536, N'class Solution:
    def intToRoman(self, num: int) -> str:
        # Saving the digists in the list, but we must note here,
        # that this digits are saving as string.
        num = list(str(num))
        # Dictionary:
        roman_number = {
                1000 : "M",
                500 : "D",
                100 : "C",
                50 : "L",
                10 : "X",
                5: "V",
                1 : "I",
                }
        s = "" # The Roman numeral
        i = len(num) - 1 # We need that to know
                        # what key of dictionary
                        # we can choose.
        for n in num:
        # Looping throut the list of strings ''num''.
            n = int(n) 
            a = 10**i
            b = 5 * a # For "V", "L", "D"
            c = roman_number[a]
            if n < 4:
                s = s + c * n
            elif n == 4:
                s = s + c + roman_number[b]
            elif n == 5:
                s = s + roman_number[b]
            elif n < 9:
                s = s + roman_number[b]  + c * (n - 5)
            elif n == 9:
                s = s + c + roman_number[10*a]
            i = i - 1
        return s', N'Only 5 cases, easy to understand whit explanation', 544, 12, 1);
