INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (539, N'class Solution:
    def intToRoman(self, num: int) -> str:
        SYMBOLS =  ''M'', ''CM'', ''D'', ''CD'', ''C'', ''XC'', ''L'', ''XL'', ''X'', ''IX'', ''V'', ''IV'', ''I''
        VALUES  = 1000,  900, 500, 400,  100,  90,  50,   40,  10,    9,   5,    4,   1

        rom = ''''
        for numeral, divisor in zip(SYMBOLS, VALUES):
            quot, num = divmod(num, divisor)
            rom += numeral * quot

        return rom', N'Reduce-based Solution, The Best', 240, 12, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (540, N'class Solution:
    def intToRoman(self, num: int) -> str:
        SYMBOLS =  ''M'', ''CM'', ''D'', ''CD'', ''C'', ''XC'', ''L'', ''XL'', ''X'', ''IX'', ''V'', ''IV'', ''I''
        VALUES  = 1000,  900, 500, 400,  100,  90,  50,   40,  10,    9,   5,    4,   1

        return reduce(self.produceSymbols, zip(SYMBOLS, VALUES), (num, ''''))[1]

    def produceSymbols(self, num_rom: tuple[int, str], sym_div: tuple[str, int]) -> tuple[int, str]:
        num, rom = num_rom
        sym, div = sym_div
        return num % div, rom + sym * (num // div)', N'Reduce-based Solution, The Best', 240, 12, 3);
