        sum = 0
        for symbol, val in mapping.items():
            sum += s.count(symbol) * val
        return sum', N'Python 3 solution less than 98% Memory Usage with explanation.', 258, 13, 1500);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (553, N'class Solution:
    def romanToInt(self, s: str) -> int:
        roman_to_int = {
            ''I'' : 1,
            ''V'' : 5,
            ''X'' : 10,
            ''L'' : 50,
            ''C'' : 100,
            ''D'' : 500,
            ''M'' : 1000
        }
        
        result = 0
        prev_value = 0
        for letter in s:
            value = roman_to_int[letter]
            result += value
            if value > prev_value:
                # preceding roman nummber is smaller
                # we need to undo the previous addition
                # and substract the preceding roman char
                # from the current one, i.e. we need to
                # substract twice the previous roman char
                result -= 2 * prev_value
            prev_value = value
        return result', N'Python Solution with explanantion', 622, 13, 3700);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (554, N'class Solution:
    def romanToInt(self, s: str) -> int:
        a, r = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000, "IV": -2, "IX": -2, "XL": -20, "XC": -20, "CD": -200, "CM": -200}, 0
        for d, e in a.items():
            r += s.count(d) * e
        return r', N'[PYTHON 3] BEATS 99.13% | EASY TO UNDERSTAND', 639, 13, 1600);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (555, N'class Solution:
    def romanToInt(self, s: str) -> int:
        '''''' faster solution which doesn''t require iterating through every element of s (currently faster than 99.49% of submissions''''''

        # store all possible conversions
        roman_conversion = {"IV": 4, "IX": 9, "XL": 40, "XC": 90, "CD": 400, "CM": 900, "I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

        ret = 0

        # dictionary is ordered, so we find if string contains special cases first
        for k, v in roman_conversion.items():
            if k in s:
                ret += s.count(k) * v
                s = s.replace(k, "")

        return ret', N'Clean, efficient, and easy-to-read Python, beats 99.5%.', 632, 13, 937);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (556, N'class Solution:
