INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (557, N'class Solution:
    def romanToInt(self, s: str) -> int:
        dic = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
        res, tmp = 0, 0
        for i in reversed(s):
            if dic[i]>=tmp:
                res=res+dic[i]
            else:
                res=res-dic[i]
            tmp=dic[i]
        return res', N'Python solution (48ms 14.3MB) - using a reversed string.', 394, 13, 983);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (558, N'class Solution:
