INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (562, N'class Solution(object):
    def romanToInt(self, s):
        """
        :type s: str
        :rtype: int
        """
        roman_dic = {
            "I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000,
            }

  
        skip_next_n = False
        int_sum = 0
        for idx, n in enumerate(s):
            if skip_next_n == True:
                skip_next_n = False
                continue
            try:
                if roman_dic[n] < roman_dic[s[idx + 1]]:
                    int_sum +=  roman_dic[s[idx + 1]] - roman_dic[n]
                    skip_next_n = True
                    continue
                else:
                    int_sum += roman_dic[n]
            except:
                int_sum += roman_dic[n]
                
        return int_sum', N'EASY PYTHON SOLUTION', 596, 13, 2600);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (563, N'class Solution:
    def romanToInt(self, s: str) -> int:
        map_ = {"I":1 ,"V":5, "X":10, "L":50, "C":100, "D":500, "M":1000}
        val = 0
        i = len(s)-1
        
        while i >= 0:
            if map_[s[i]] > map_[s[i-1]] and i != 0:
                val += (map_[s[i]]-map_[s[i-1]])
                i -= 1
            else:
                val += map_[s[i]]
            i -= 1
        
        return val', N'Faster than 99% and with hash table.', 593, 13, 811);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (564, N'class Solution:
    def romanToInt(self, s: str) -> int:
        
        roman_val = {''I'': 1, ''V'': 5, ''X'': 10, ''L'': 50, ''C'': 100, ''D'': 500, ''M'': 1000}
        value = 0
        
        for i in range(0, len(s)-1):
            
            # If we have low value char before higher value then it should be subtracted
            # Like ''IV'' or ''IX'' or ''CM''
            if(roman_val[s[i]] < roman_val[s[i+1]]):
                value -= roman_val[s[i]]
            # Else add up the value of character like ''XII or ''MX''
            else:
                value += roman_val[s[i]]
                
        value += roman_val[s[-1]]
        return value', N'Roman to Integer || Python3 || Easy', 410, 13, 370);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (565, N'class Solution:
	"""
	Time:   O(1)
	Memory: O(1)
	"""

	ROMAN_TO_INTEGER = {
		''I'':  1,
		''IV'': 4,
		''V'':  5,
		''IX'': 9,
		''X'':  10,
		''XL'': 40,
		''L'':  50,
		''XC'': 90,
		''C'':  100,
		''CD'': 400,
		''D'':  500,
		''CM'': 900,
		''M'':  1000,
	}

	def romanToInt(self, s: str) -> int:
		converted = 0

		for roman, integer in self.ROMAN_TO_INTEGER.items():
			while s.endswith(roman):
				s = s.removesuffix(roman)
				converted += integer

		return converted', N'Python Elegant & Short | 93.51% faster | Constant time and memory', 194, 13, 404);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (566, N'class Solution:
	def romanToInt(self, s: str) -> int:
		dict_normal = {''I'': 1, ''V'': 5, ''X'': 10, ''L'': 50, ''C'': 100, ''D'': 500, ''M'': 1000}
		dict_subtract = {''IV'': 1, ''IX'': 1, ''XL'': 10, ''XC'': 10, ''CD'': 100, ''CM'': 100}
		sum_all = sum([dict_normal[s_letter] for s_letter in list(s)])
		sum_deduct = sum([dict_subtract[subtract_key] for subtract_key in dict_subtract.keys() if subtract_key in s])
		return sum_all - sum_deduct * 2', N'Python Solution with ''subtraction'' idea', 513, 13, 445);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (567, N'class Solution:
    def romanToInt(self, roman: str) -> int:
        convert = {''IV'':''IIII'', ''IX'':''VIIII'', ''XL'':''XXXX'', ''XC'':''LXXXX'', ''CD'':''CCCC'', ''CM'':''DCCCC''}
        roman_units = {''M'':1000, ''D'':500, ''C'':100, ''L'':50, ''X'':10, ''V'':5, ''I'':1}
        
        for key in convert.keys():
            if key in roman:
                roman = roman.replace(key, convert[key])
            
        return sum([roman_units[i] for i in roman])', N'[Python 3] Simple code using dictionary', 616, 13, 281);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (568, N'class Solution:
    def romanToInt(self, s: str) -> int:
        sym = ''IVXLCDM''
        val = [1,5,10,50,100,500,1000]
        highest, res = 0, 0
        for i in s[::-1]:
            ix = sym.index(i)
            if ix >= highest:
                res += val[ix]
                highest = ix
            else:
                res -= val[ix]
        return res', N'Creative no-dictionary Python Solution', 234, 13, 794);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (569, N'class Solution:  # Time: O(n) and Space: O(1)
    def romanToInt(self, s: str) -> int:

        # From Smallest Roman value to Biggest.
        roman = {
            ''I'': 1,
            ''V'': 5,
            ''X'': 10,
            ''L'': 50,
            ''C'': 100,
            ''D'': 500,
            ''M'': 1000
        }

        # Smaller roman after Bigger: add it to the Bigger one i.e. VIII = 8
        # Smaller roman before Bigger: subtract it to the Bigger one i.e. IV = 5 - 1 = 4

        res = 0

        for i in range(len(s)):
            if i + 1 < len(s) and roman[s[i]] < roman[s[i + 1]]:  # if there exist i+1 index and Smaller Roman is before Bigger
                res -= roman[s[i]]
            else:                                                 # if there exist only one index or Smaller Roman is after Bigger
                res += roman[s[i]]
        return res', N'Python Simple O(n) Solution with full working explanation', 28, 13, 672);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (570, N'class Solution:
