        return ans', N'Easy Python Solution Using Dictionary', 496, 13, 483);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (571, N'class Solution(object):
    def romanToInt(self, s):
        """
        :type s: str
        :rtype: int
        """
        d = {''I'':1, ''V'':5, ''X'':10, ''L'':50, ''C'':100, ''D'':500, ''M'':1000}
        num = 0
        for i in range(len(s)-1):
            # If the next letter has larger value than the current, the current letter subtracts
            if d[s[i]] < d[s[i+1]]:
                num -= d[s[i]]
            # If not, it adds
            else:
                num += d[s[i]]
        # Add the last number
        num += d[s[-1]]
        return num', N'Simple Python solution', 338, 13, 307);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (572, N'class Solution:
    def romanToInt(self, s: str) -> int:
        convertedInt = 0
        romanHashmap = {
            "I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000,
        }
        prevChar = None
        for i in range(0, len(s)):
            currChar = s[i]
            # Only do comparison once something has been stored in variable ''prevChar''
            if (i > 0) and (romanHashmap[currChar] > romanHashmap[prevChar]):
                convertedInt = convertedInt - 2*romanHashmap[prevChar] + romanHashmap[currChar]
            else:
                convertedInt += romanHashmap[currChar]
			# Store current character in variable ''prevChar'' for comparison in next iteration
            prevChar = currChar
                    
        return convertedInt', N'Easy to understand Python solution', 629, 13, 598);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (573, N'class Solution:
    def romanToInt(self, s: str) -> int:
        map={
