INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (574, N'class Solution:
    def romanToInt(self, s: str) -> int:
        lookup = {
            ''I'':1,
            ''V'': 5,
            ''X'':10,
            ''L'':50,
            ''C'':100,
            ''D'':500,
            ''M'':1000,
        }
        integer = 0
        prev = cur = lookup[s[0]]
        
        for i in s[1:]:
            if lookup[i] <= prev:
                cur += lookup[i]
            else:
                cur += lookup[i] - 2*prev
            prev = lookup[i]
    
        return cur', N'Logic explained in detail.', 199, 13, 222);
