INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (577, N'class Solution:
    
    def romanToInt(self, s: str) -> int:
        symbolsValue = {''IV'':4,''IX'':9,''XL'':40,''XC'':90,''CD'':400,''CM'':900,
