INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (585, N'class Solution:
    def romanToInt(self, s: str) -> int:
        hashmap = {''I'': 1, ''V'': 5, ''X'': 10, ''L'': 50, ''C'': 100, ''D'': 500, ''M'': 1000}
        total, prev = 0, 0
        for i in s:
            cur = hashmap[i]
            if cur > prev:
                total -= prev
                total += cur - prev
            else:
                total += cur
            prev = cur
        return total', N'36 ms', 482, 13, 168);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (586, N'class Solution:
    def romanToInt(self, s: str) -> int:
        sym=["I","V","X","L","C","D","M"]
        val=[1,5,10,50,100,500,1000]
        sum=0
        l=len(s)
        flag=0
        i=0
        while i <l-1:
            fp=sym.index(s[i])
