INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (587, N'class Solution:
    def romanToInt(self, s: str) -> int:
        
        translation = {"I": 1,
               "V": 5,
               "X": 10,
               "L": 50,
               "C": 100,
               "D": 500,
               "M": 1000}

        l1 = [translation[i] for i in s]
        l1.reverse()

        num = 0
        
        for idx, i in enumerate(l1):
            if idx == 0:
                num += i
            elif i < l1[idx - 1]:
                num = num - i
            else:
                num += i
        
        return num', N'Smooth Python 3 solution (>98%)', 577, 13, 1100);
