INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (592, N'class Solution:
    def romanToInt(self, s: str) -> int:
        convert = {
            ''I'': 1,
            ''V'': 5,
            ''X'': 10,
            ''L'': 50,
            ''C'': 100,
            ''D'': 500,
            ''M'': 1000
        }
        
        out = 0
        prev = 0 # store last added to compare to current
        
        for i in range(len(s) - 1, -1, -1):
            # Case: numbers like 4, written as IV, where smaller number precedes larger one
            if(prev > convert[s[i]]): 
                out -= convert[s[i]]
            else: 
                # Default case: next digit is the same as or larger than previous one
                out += convert[s[i]]
            
            # Update prev digit
            prev = convert[s[i]]
            
        return out', N'Generalised Python 3 Solution', 435, 13, 256);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (593, N'class Solution(object):
    def romanToInt(self, s):
        """
        :type s: str
        :rtype: int
        """
        roman_symobols = {
            "I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000,
        }
        total = 0
        previous_rim = s[-1]
        for i in s[::-1]:
            roman_int = roman_symobols[i]
            if roman_symobols[previous_rim] > roman_int:
                total -= roman_int
                continue
            previous_rim = i
            total += roman_int
        return total', N'Simple Python Solution || 92% Faster', 386, 13, 333);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (594, N'class Solution:
	def romanToInt(self, s: str) -> int:
		result = 0
		values = {
			"I": 1,
			"V": 5,
			"X": 10,
			"L": 50,
			"C": 100,
			"D": 500,
			"M": 1000,

			# Substraction letters
			"Q": 4,
			"W": 9,
			"E": 40,
			"R": 90,
			"T": 400,
			"Y": 900,
		}

		# Replacing substractions
		replacements = {
			"IV": "Q",
			"IX": "W",
			"XL": "E",
			"XC": "R",
			"CD": "T",
			"CM": "Y",
		}

		# Check for substractions and replacing
		for pair in replacements:
			s = s.replace(pair, replacements[pair])

		# Calculating
