INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (621, N'class Solution:
    def zigzagLevelOrder(self, root):
       
	    // based on dfs
        def divide_conquer(root, depth):
            if root is None: return {}
            
			// store root''s value of this depth(level)
            small_answer = {}
            small_answer[depth] = [root.val]
                
			// divide current problem with left smaller problem and right smaller problem
            l = divide_conquer(root.left, depth + 1)
            r = divide_conquer(root.right, depth + 1)
            
			// get two parts that have been resolved
            conquered_level = depth + 1
            conquered_l = l.get(conquered_level, [])
            conquered_r = r.get(conquered_level, [])
            
			// merge two parts by the rules
            while conquered_l != [] or conquered_r != []:
                if conquered_level % 2 == 0:
                    small_answer[conquered_level] = conquered_r + conquered_l
                else:
                    small_answer[conquered_level] = conquered_l + conquered_r
                    
                conquered_level += 1
                conquered_l = l.get(conquered_level, [])
                conquered_r = r.get(conquered_level, [])
            
			// and also this answer will be one part of the higher level
            return small_answer
        
        return divide_conquer(root, 1).values()', N'???? [Python] O(n) (92.34%) (No Queue) Divide and Conquer Solution', 233, 103, 18);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (622, N'class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        stack = [root]
        final = []
        div = 1
        if(not(root)):return
        while(stack):
            temp, temp1 = [], []
            for _ in range(len(stack)):
                value = stack.pop(0)
                temp1.append(value.val)
                if(value.left):temp.append(value.left)
                if(value.right):temp.append(value.right)
            stack = temp
            if(div % 2 == 0): final.append(temp1[::-1])
            else: final.append(temp1)
            div += 1
        return (final)', N'Python BFS Beats 97% - Simple change', 308, 103, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (623, N'class Solution(object):
    def zigzagLevelOrder(self, root):
        """
        :type root: TreeNode
        :rtype: List[List[int]]
        """

        if root is None:
            return []
        
        level_values = dict()
        
        def bfs(node, level):
            if node is None:
                return
            
            if level not in level_values:
                level_values[level] = []
            
            level_values[level].append(node.val)
            bfs(node.left, level + 1)
            bfs(node.right, level + 1)
            
        
        bfs(root, 0)
        max_level = max(level_values.keys())
        zigzag = []
        for pos, level in enumerate(range(max_level + 1)):
            level_data = level_values[level]
            if level % 2 == 1: # reversed row
                level_data = level_data[::-1]
            zigzag.append(level_data)
        
        return zigzag', N'Python 3 Super easy to understand!', 65, 103, 64);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (624, N'class Solution(object):
