            for i in range(qLen):
                node=q.pop(0)
                level.append(node.val)
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
                    
            if not z:
                res.append(level[::-1])
            else:
                res.append(level)
            z=not z
