INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (625, N'class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:

        ans = []
        cur_level, cur_level_nodes = 0, []

		# initialise and add root in queue with level as 0
        q = deque()
        q.append((root, 0))

        while q:
			# get first element from the queue and its resp. level
            node, level = q.popleft()
            if node is None:
                continue

			# if level is same, append nodes value
			# else change level and append nodes value
            if level == cur_level:
                cur_level_nodes.append(node.val)
            else:
				# reverse the list if cur_level is even
                ans.append(cur_level_nodes[::(-1 if cur_level%2 else 1)])
                cur_level = level
                cur_level_nodes = [node.val]

			# add left and right children in queue with level as parent''s level + 1
            q.append((node.left, level+1))
            q.append((node.right, level+1))

        if len(cur_level_nodes):
            ans.append(cur_level_nodes[::(-1 if cur_level%2 else 1)])

        return ans', N'?? Simple Python Solution  ||   BFS', 104, 103, 24);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (626, N'class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        res = []
        if(root == None):
            return res
        
        q = deque()
        q.append(root)
        check = True
        while(q):
            sz = len(q)
            curr = []
            for i in range(sz):
                temp = q.popleft()
                
                curr.append(temp.val)
                
                if(temp.left):
                    q.append(temp.left)
                    
                if(temp.right):
                    q.append(temp.right)
                    
            if(check):
                res.append(curr)
            else:
                res.append(curr[::-1])
            
            check = not check
            
        return res', N'super easy solution with trick and comments  TC: O(N) SC : O(N)', 149, 103, 30);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (627, N'class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        # Same as level order traversal, but here we use count to store levels
        # in alternate fashion
        # T(n)=O(n)
        def helper(root,res):
            if root is None:
                return 
            q=deque()
            q.append(root)
            count=0
            while q:
                count+=1
                path=[]
                size=len(q)
                for _ in range(size):
                    node=q.popleft()
                    path+=[node.val]
                    if node.left:
                        q.append(node.left)
                    if node.right:
                        q.append(node.right)
                if count%2:
                    res.append(path)
                else:
                    res.append(path[::-1])
            return res
        res=[]
        return helper(root,res)', N'simple python solution', 130, 103, 35);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (628, N'class Solution:
