INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (643, N'class Solution:
       
    def maxDepth(self, root: TreeNode) -> int:
        
        self.tree_depth = 0
        
        def helper( node: TreeNode, depth: int):
            
            if not node:
				# Base case
				# Empty node or empty tree
                return
        
            if not node.left and not node.right:
				# Base case
				# Update max depth when reach leaf node
                self.tree_depth = max( self.tree_depth, depth )
            
            else:
				# General case
				# Keep DFS down to next level
                helper( node.left, depth + 1)
                helper( node.right, depth + 1)
        
        # ------------------------------------------------
        helper( node = root, depth = 1 )
        return self.tree_depth', N'Python/JS/Go/C++ by O(n) DFS [w/ Comment ]', 303, 104, 479);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (644, N'class Solution:
	def maxDepth(self, root: Optional[TreeNode]) -> int:
		if not root:
			return 0

		res = 1
		stack = [[root, 1]]
		while stack:
			node, depth = stack.pop()

			if node:
				res = max(res, depth)
				stack.append([node.left, depth+1])
				stack.append([node.right, depth+1])

		return res', N'Python DFS recursive  || BFS || DFS iterative solution', 444, 104, 22);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (645, N'class Solution:
	def maxDepth(self, root: Optional[TreeNode]) -> int:
		if not root:
