INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (671, N'class Solution:

    def maxDepth(self, root: Optional[TreeNode]):
        queue = []
        height = 0
        if not root:
            return 0
        queue.append(root)

        while queue:
            current_length = len(queue)
            height += 1
            for _ in range(0, current_length):
                popped_elem = queue.pop(0)
                if popped_elem.left:
                    queue.append(popped_elem.left)
                if popped_elem.right:
                    queue.append(popped_elem.right)

        return height', N'I hate DFS so came up with BFS Python', 421, 104, 2);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (672, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> TreeNode:
        loc = {x : i for i, x in enumerate(inorder)}
        root = None
        stack = []
        for x in preorder: 
            if not root: root = node = TreeNode(x)
            elif loc[x] < loc[node.val]: 
                stack.append(node)
                node.left = node = TreeNode(x)
            else: 
                while stack and loc[stack[-1].val] < loc[x]: node = stack.pop() # backtracking
                node.right = node = TreeNode(x)
        return root', N'[Python3] stack O(N)', 4, 105, 371);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (673, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> TreeNode:
        loc = {x: i for i, x in enumerate(inorder)}
        pre = iter(preorder)
        
        def fn(lo, hi): 
            """Return node constructed from inorder[lo:hi]."""
            if lo == hi: return None
            k = loc[next(pre)]
            return TreeNode(inorder[k], fn(lo, k), fn(k+1, hi))
        
        return fn(0, len(inorder))', N'[Python3] stack O(N)', 4, 105, 371);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (674, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> TreeNode:
        loc = {x: i for i, x in enumerate(inorder)}
        k = 0 
        
        def fn(lo, hi): 
            """Return BST constructed from inorder[lo:hi]."""
            nonlocal k 
            if lo < hi: 
                val = preorder[k]
                mid = loc[val]
                k += 1
                return TreeNode(val, fn(lo, mid), fn(mid+1, hi))
        
        return fn(0, len(inorder))', N'[Python3] stack O(N)', 4, 105, 371);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (675, N'class Solution:
    def buildTree(self, preorder, inorder):
        inorderIndexDict = {ch : i for i, ch in enumerate(inorder)}
        self.rootIndex = 0
        
        def solve(l, r):
            if l > r: return None
            
            root = TreeNode(preorder[self.rootIndex])
            self.rootIndex += 1
            
            i = inorderIndexDict[root.val]
            
            root.left = solve(l, i-1)
            root.right = solve(i+1, r)
            
            return root
        
        return solve(0, len(inorder)-1)
    
    
# Time: O(N)
# Space: O(1)', N'[Python3] O(N) Time, O(1) Space Recursive Solution', 470, 105, 206);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (676, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        if len(preorder) == 0:
            return None
        
		# This gives the root data
        rootData = preorder[0]
        root = TreeNode(rootData)
        rootIdx = -1
        for i in range(len(inorder)):
            if rootData == inorder[i]:
                rootIdx = i
                break
                
        if rootIdx == -1:
            return None
        # This gives the leftInorder
        leftInorder = inorder[:rootIdx]
		#This gives the rightInorder
        rightInorder = inorder[rootIdx+1:]
        
        lenLeftSubTree = len(leftInorder)
        
        leftPreorder = preorder[1:lenLeftSubTree+1]
        rightPreorder = preorder[lenLeftSubTree+1:]
        
		# Recursion will build the tree 
        leftChild = self.buildTree(leftPreorder, leftInorder)
        rightChild = self.buildTree(rightPreorder, rightInorder)
        
		# Making connnections of the tree
        root.left = leftChild
        root.right = rightChild
        
        return root', N'Python | Readable Solution | Recursion', 288, 105, 312);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (677, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        def makeNode(p, i, j):
            if j-i < 1:
                return None
            p[0] += 1
            return TreeNode(inorder[i]) if j-i == 1 else makeTree(p,i,j)
