INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (702, N'class Solution(object):
    def buildTree(self, preorder, inorder):
        """
        :type preorder: List[int]
        :type inorder: List[int]
        :rtype: TreeNode
        """
        if not preorder or not inorder:
            return None
        root = TreeNode(preorder[0])
        mid = inorder.index(preorder[0])
        root.left = self.buildTree(preorder[1:mid+1], inorder[:mid])
        root.right = self.buildTree(preorder[mid + 1:], inorder[mid + 1:])
        return root', N'Python Easy Solution', 448, 105, 58);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (703, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        def build(preorder, inorder, l, r):
            if l == r:
                return
            
            root_val = preorder.pop(0)
            root_index = inorder.index(root_val)

            root = TreeNode(root_val)
            root.left = build(preorder, inorder, l, root_index)
            root.right = build(preorder, inorder, root_index + 1, r)

            return root
        
        return build(preorder, inorder, 0, len(inorder))', N'Python | Recursion |  O(n) time O(n) space', 95, 105, 45);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (704, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        
        #EdgeCase
        if len(preorder) == 0 : return 
        
        rootData = preorder[0]
        root = TreeNode(rootData)
        
        #Finding Index
        rootIndex = -1
        
        for i in range(0, len(inorder)) :
            if inorder[i] == rootData :
                rootIndex = i
                break
        
        #Something is wrong in input
        if rootIndex == -1 :
            return None
        
        #Inorder
        leftInorder = inorder[ : rootIndex ]
        rightInorder = inorder[ rootIndex + 1 : ]
        
        #Preorder
        leftPreorder = preorder[ 1 : len(leftInorder) + 1 ]
        rightPreorder = preorder[ len(leftInorder) + 1 : ]
        
        #Recursively constructing nodes
        leftChild = self.buildTree( leftPreorder, leftInorder )
        rightChild = self.buildTree( rightPreorder, rightInorder )
        
        #Joining childs to root
        root.left = leftChild
        root.right = rightChild
        
        return root', N'Recursive | Step-wise clear approach | Python3', 304, 105, 44);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (705, N'class Solution(object):
    def buildTree(self, preorder, inorder):
        """
        :type preorder: List[int]
        :type inorder: List[int]
        :rtype: TreeNode
        """
        
        inmap={}
        
        for i,v in enumerate(inorder):
            inmap[v]=i
            
        return self.helper(preorder, inmap,0,len(preorder)-1,0,len(inorder)-1)
        
    def helper(self, preorder, inmap, pre_left, pre_right, in_left, in_right):
        if in_right<in_left:
            return None
        
        root=TreeNode(preorder[pre_left])
        root_position=inmap[root.val]
        left_len=root_position - in_left
        
        root.left=self.helper(preorder, inmap,pre_left+1,pre_left+left_len,in_left, root_position-1)
        
        root.right=self.helper(preorder,inmap,pre_left+left_len+1,pre_right, root_position+1, in_right)
        
        return root', N'DFS left right boundary', 493, 105, 28);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (706, N'class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        def helper(preorder, inorder):
            if not preorder:
                return None
            ans = TreeNode(val = preorder.pop(0))
            if not preorder:
                return ans
            left = set()
            left_in, left_pre = [], []
            while inorder and inorder[0] != ans.val:
                left_in.append(inorder.pop(0))
                left.add(left_in[-1])
            inorder.pop(0)
            while preorder and preorder[0] in left:
                left_pre.append(preorder.pop(0))
            ans.left = helper(left_pre, left_in)
            ans.right = helper(preorder, inorder)
            return ans
        return helper(preorder, inorder)', N'slow and easy to understand python stack solution', 432, 105, 35);
