INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (712, N'class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        def util(inorder,postorder,n):
            if not inorder or not postorder:
                return None
            root = TreeNode(postorder[-1])
            mid = inorder.index(postorder[-1])
            root.left = util(inorder[:mid],postorder[:mid],mid)
            root.right = util(inorder[mid+1:],postorder[mid:n-1],n-mid-1)
            return root
        return util(inorder,postorder,len(inorder))', N'Index Recursion approach | Python', 281, 106, 51);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (713, N'class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> TreeNode:
        def build(a, b, c, postorder, inorder):
            if a < 0 or b > c:
                return
            root = TreeNode(postorder[a])
            x = inorder.index(postorder[a],b,c+1)
            root.left = build(a - (c - (x+1) + 1)-1, b, x-1, postorder, inorder)
            root.right = build(a-1, x+1, c, postorder, inorder)
            return root
        return build(len(postorder)-1, 0, len(inorder)-1, postorder, inorder)', N'Python3 simple solution using recursion', 145, 106, 64);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (714, N'class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        loc = {x : i for i, x in enumerate(inorder)}
        root = None
        stack = []
        for x in reversed(postorder): 
            if not root: root = node = TreeNode(x)
            elif loc[node.val] < loc[x]: 
                stack.append(node)
                node.right = node = TreeNode(x)
            else: 
                while stack and loc[x] < loc[stack[-1].val]: node = stack.pop()
                node.left = node = TreeNode(x)
        return root', N'[Python3] stack O(N)', 4, 106, 246);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (715, N'class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> TreeNode:
        mp = {v: i for i, v in enumerate(inorder)} #mapping from val to pos
        
        def fn(lo, hi): 
            """Return sub-tree root from inorder[lo:hi]"""
            if lo == hi: return None
            mid = mp[(val := postorder.pop())]
            return TreeNode(val, right=fn(mid+1, hi), left=fn(lo, mid))
        
        return fn(0, len(inorder))', N'[Python3] stack O(N)', 4, 106, 246);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (716, N'class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        dic = {}
        
        for idx, val in enumerate(inorder):
            dic[val] = idx
        
        def f(start, end):
            if start > end:
                return None
            node = TreeNode(postorder.pop())
            index = dic[node.val]
            node.right = f(index+1, end)
            node.left = f(start, index-1)
            return node

        return f(0, len(inorder)-1)', N'Python Sol.  Faster then 97.78%', 196, 106, 9);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (717, N'class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        m = {}
        for i in range(len(inorder)):
            m[inorder[i]] = i
            
        def helper(in_l, in_r, inorder, po_l, po_r, postorder):
            if po_l >= po_r:
                return TreeNode(postorder[po_r])
            curr = TreeNode(postorder[po_r])
            idx = m[postorder[po_r]]
            num_right_tree = in_r - idx
            num_left_tree = idx - in_l
            if num_right_tree > 0:
                curr.right = helper(idx+1, in_r, inorder, po_r-num_right_tree, po_r-1, postorder)
            if num_left_tree > 0:
                curr.left = helper(in_l, idx-1, inorder, po_l, po_l+num_left_tree-1, postorder)
            return curr
        
        return helper(0, len(inorder)-1, inorder, 0, len(postorder)-1, postorder)', N'Python DFS O(n), O(n)', 477, 106, 78);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (718, N'class Solution:
    def helper(self, result, depth, node):
        if not node:
            return
        
        if len(result) < depth:
            result.append([])
            
        result[depth-1].append(node.val)
        self.helper(result, depth+1, node.left)
        self.helper(result, depth+1, node.right)
        
    def levelOrderBottom(self, root: TreeNode) -> List[List[int]]:
        if not root:
            return []
        
        result = []
        depth = 1
        self.helper(result, depth, root)
        result.reverse()
        return result', N'Python recursive and iterative', 622, 107, 519);
