            size=len(q)
            for _ in range(size):
                node=q.popleft()
                path+=[node.val]
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            res.appendleft(path)
        return res', N'simple python bfs solution', 130, 107, 15);
