INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (730, N'class Solution:
    def levelOrderBottom(self, root: Optional[TreeNode]) -> List[List[int]]:
        def reversed_bfs(level: List[TreeNode]):
            if not level:
                return []
            yield from reversed_bfs([c for n in level for c in (n.left, n.right) if c])
            yield [n.val for n in level]
        
        return list(reversed_bfs([root])) if root else []', N'Bottom-up BFS in Python 3, using generator without extra module in 6 lines', 433, 107, 58);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (731, N'class Solution:
    def levelOrderBottom(self, root: TreeNode) -> List[List[int]]:
        if not root: return []
        
        # queue contains (node, level)
        q = collections.deque([(root, 0)])
        # key=row, value=list of nodes in row
        ans = collections.defaultdict(list)
        # BFS
        while q:
            temp = q.popleft()
            node, row = temp[0], temp[1]
            ans[row].append(node.val)
            if node.left:
                q.append((node.left, row+1))
            if node.right:
                q.append((node.right, row+1))
          
        # Obtain values of ans dictionary and reverse
        return list(ans.values())[::-1]', N'Python BFS', 205, 107, 59);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (732, N'class Solution:
