INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (733, N'class Solution:
    def levelOrder(self, root: TreeNode) -> List[List[int]]:
        if root is None: # Base case
            return []
        
        result = [[root.val]]   # result starts with root node value
        queue = [root] # Queue starts with root node
        
        while queue:
            level = [] # keep nodes of each the level
	
            while queue: # can also be done using foor loop instead of while loop
                node = queue.pop(0)
                if node.left:
                    level.append(node.left)
                if node.right:
                    level.append(node.right)
            
            queue = level # Replace queue with current level nodes
			# if we have something in this level, add it to the final result list
            if len(level): 
                result.append([each.val for each in level])
                
        return result[::-1]', N'Easy Python Solution with BFS', 10, 107, 47);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (734, N'class Solution:
    def levelOrderBottom(self, root: TreeNode) -> List[List[int]]:
        result: List[List[int]] = []
            
        if not root:
            return result
        
        queue: Deque[TreeNode] = deque([root])
        count: int = 0
            
        while queue:
