INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (738, N'class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> TreeNode:
        # base case
        if not nums: return None
        
        # getting the mid
        mid = len(nums)//2
        node = TreeNode(nums[mid])
        
        # left node is given the responsibility till mid, 
        # but not including mid
        node.left = self.sortedArrayToBST(nums[:mid])
        # right node is given the responsibility from mid+1 
        # till the end
        node.right = self.sortedArrayToBST(nums[mid+1:])
        return node', N'[Python3] Two Solutions Explained with Diagrams', 121, 108, 833);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (739, N'class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> TreeNode:
        def recurse(l, r):
            # base case, l must always be <= r
            # l == r is the case of a leaf node.
            if l > r: return None
            mid = (l+r)//2
            node = TreeNode(nums[mid])
            node.left = recurse(l, mid-1)
            node.right = recurse(mid+1, r)
            return node
        # both the indices are inclusive,
        # mathematically given by: [0, len(nums)-1]
        return recurse(0, len(nums)-1)', N'[Python3] Two Solutions Explained with Diagrams', 121, 108, 833);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (740, N'class Solution:
	"""
	Time:   O(n)
	Memory: O(log(n))
	"""

	def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
		return self._construct(0, len(nums) - 1, nums)

	@classmethod
	def _construct(cls, left: int, right: int, nums: List[int]) -> Optional[TreeNode]:
		if left <= right:
			mid = (left + right) // 2
			return TreeNode(
				val=nums[mid],
				left=cls._construct(left, mid - 1, nums),
				right=cls._construct(mid + 1, right, nums),
			)', N'Python Elegant & Short | O(n) time & O(log(n)) space', 194, 108, 78);
