INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (747, N'class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
		def buildBST(nums, start, end) :
				#Edge Case
				if start > end :
					return None

				#Creating a new node
				newNode = TreeNode()

				if start == end :
					newNode.val = nums[start]
					newNode.left = None
					newNode.right = None
				else :
					mid = start + (end - start) // 2
					newNode.val = nums[mid]
					newNode.left = buildBST(nums, start, mid - 1)
					newNode.right = buildBST(nums, mid + 1, end)

				return newNode

		return buildBST(nums, 0, len(nums)-1)', N'97% FAST!! | PYTHON3 | RECURSIVE SOLUTION', 304, 108, 141);
