INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (764, N'class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        if not head:
            return None
        nums = []
        L = 0
        while head is not None:
            nums.append(head.val)
            head = head.next
            L += 1
        #Convert to array first
        root = TreeNode(val=0)
        def buildTree(node, nums, lo, hi):
            if lo > hi:
                return None
			#Algorithm: Due to the balanced requirement, the inserted value has to be in the middle. 
			#This process is similar to binary search, or quick sort. In fact, quick sort is to build a binary search tree. 
			#That''s why if the array is sorted already and pivot was not randomly selected, the time complexity goes up to O(n^2),
			#because the binary search tree became "IMBALANCED" and become a one-sided tree (or a linked list)
            mid = (lo+hi)//2
            node = TreeNode(val=nums[mid])
            node.left = buildTree(node.left, nums, lo, mid-1)
            node.right = buildTree(node.right, nums, mid+1, hi)
            return node
        
        root = buildTree(root, nums, 0, L-1)
        return root', N'Python | DFS | Recursion | Convert To Array', 514, 109, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (765, N'class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        # Base case
        if not head:
            return None
        elif not head.next:
            return TreeNode(head.val)

        # Divide into half
        slow, fast = head, head.next.next
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next

        # Get mid
        mid = slow.next
        slow.next = None

        # Root is mid (recurse through left &amp; right)
        root = TreeNode(mid.val)
        root.left = self.sortedListToBST(head)
        root.right = self.sortedListToBST(mid.next)
        return root', N'Python Simple Recursive Solution', 484, 109, 5);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (766, N'class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        length = 0
        curr = head
        while curr:
            length += 1
            curr = curr.next

        def value(mid):
