INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (769, N'class Solution:
    def sortedListToBST(self, head):
        sorted_array = []
        curr = head
        # First convert sorted array
        while curr != None:
            sorted_array.append(curr.val)
            curr = curr.next
        # Now convert to BST, here in every level parent of subtree will be mid of the list
        # So, root will be mid of the list, then do recursively left and right subtree.
        # For left, the left and right will be from left and mid - 1, as mid is assigned to this parent
        # for right, the left and right will be from mid + 1 to right
        low = 0
        high = len(sorted_array) - 1

        def convert(left, right):
            if left > right:
                return None
            mid = (left + right) // 2
            node = TreeNode(sorted_array[mid])
            node.left = convert(left, mid - 1)
            node.right = convert(mid + 1, right)
            return node

        return convert(low, high)
		```', N'python3 - Convert to sorted array & recursively make BST', 54, 109, 26);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (770, N'class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        # I have taken a dummy node of value 69 and we will return tree.left which is our actual root
        tree = TreeNode(69)
        def helper(start,tree, isLeft):
            if start is None:
                return 
            
            prev, slow, fast = None, start, start
            while fast and fast.next:
                prev = slow
                slow = slow.next
                fast = fast.next.next
            startOne = None if start == slow else start
            startTwo = slow.next
            slow.next = None
            if prev:
                prev.next = None
            if isLeft:
                tree.left = TreeNode(slow.val)
            if not isLeft:
                tree.right = TreeNode(slow.val)
            if tree.left and isLeft:
                helper(startOne, tree.left, True)
                helper(startTwo, tree.left, False)
            if tree.right and not isLeft:
                helper(startOne, tree.right, True)
                helper(startTwo, tree.right, False)
        helper(head, tree, True)
        return tree.left', N'Python solution', 302, 109, 50);
