            if i > j:
                return None
            mid = (i+j)//2
            node = TreeNode(nums[mid])
            node.left = dfs(i,mid-1,nums)
            node.right = dfs(mid+1,j,nums)
            
            return node
        return dfs(0,len(nums)-1,nums)', N'Python O(n) Time O(n) Space Simple Easy to understand', 633, 109, 87);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (772, N'class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        
        out = []
        while head:
            out.append(head.val)
            head = head.next
        
        def helper(out):
            
            if not out:
                return None
            
            mid = len(out) // 2
            root = TreeNode(out[mid])
            root.left = helper(out[:mid])
            root.right = helper(out[mid+1:])
            
            return root
        
        return helper(out)', N'[Python] | Convert to List then Recursion', 179, 109, 65);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (773, N'class Solution:
