INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (774, N'class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        def insertNode(node):
          if not node: return node
          if not node.next: return TreeNode(node.val)
          fast = slow = node
          while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
          root = TreeNode(slow.val)
          root.right = insertNode(slow.next)
          slow.next = None
          root.left = insertNode(node)
          return root
        
        return insertNode(head)', N'Thanks for Helping', 144, 109, 55);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (775, N'class Solution:
    def build_sub_tree(self, head):
        if not head:
            return None
        
        if not head.next:
            return TreeNode(head.val)
        
        fast = slow = head
        left_tail = None
        
        while fast and fast.next:
            fast = fast.next.next
            left_tail = slow
            slow = slow.next
        
