INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (776, N'class Solution:
    def sortedListToBST(self, head: ListNode) -> TreeNode:
        array = self.findValues(head)
        return self.constructBST(array, 0, len(array)-1)

    def constructBST(self, array, left, right):
        if left <= right:
            mid = (left+right)//2
            root = TreeNode(array[mid])
            root.left = self.constructBST(array, left, mid-1)
            root.right = self.constructBST(array, mid + 1, right)
            return root

