INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (789, N'class Solution:
    def isBalanced(self, root: TreeNode) -> bool:
        
        # If root is empty
        if root==None:
            return True
        
        # Building a utility function to calculate if node is a leaf
        def is_leaf(node):
            if node.left == None and node.right==None:
                return True
            return False
        
        # A recursive function
        # Calculates if a certain node is balanced
        # 1) Checks the height of left and right children
        # 2) If unbalanced, returns "-1", otherwise returns height
        
        def get_height(node):
            
            # If the node is a leaf, height is by default 1
            if is_leaf(node):
                return 1
            
            # Creating 2 variables for the child
            left  = node.left
            right = node.right
            
            # If node has a left Child
            if left!=None:
                h_left  = get_height(left)
                left_val = left.val
                # If left child is unbalanced
                if h_left == -1:
                    return -1
            # If node doesn''t have a left child
            else:
                h_left = 0
                left_val = None
            
            # If node has a right child
            if right!=None:
                h_right = get_height(right)
                right_val = right.val
                # If right child is unbalanced
                if h_right == -1:
                    return -1
            # If node doesn''t have a right child
            else:
                h_right = 0
                right_val = None
            
            # If the left and right heights differ by more than 1 points
            if abs(h_left-h_right)>1:
                return -1
            
            # If everything went well
            return max(h_left, h_right)+1
        
        res = get_height(root)
        if res==-1:
            return False
        return True', N'Python | Time Complexity O(n) | Faster than 99.56% | Simple & Clean | Space Complexity O(1) |', 322, 110, 423);
