INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (792, N'class Solution:
	def isBalanced(self, root: Optional[TreeNode]) -> bool:
		if not root: return True

		def height(root):
			if not root: return -1
			h , Q = 0, deque([[root]])
			while Q:
				level, new_level = Q.popleft(), []
				for node in level:
					if node.right: new_level.append(node.right)
					if node.left : new_level.append(node.left)
				if new_level: 
					h += 1
					Q.append(new_level)
			return h

		Q = deque([[root]])
		while Q:
			level, new_level = Q.popleft(), []
			for node in level:
				h_left, h_right = height(node.left), height(node.right)
				if abs(h_left-h_right) > 1: return False
				if node.right: new_level.append(node.right)
				if node.left : new_level.append(node.left)
			if new_level: 
				Q.append(new_level)

		return True', N'Python || Simple Iterative BFS using Deque', 532, 110, 201);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (793, N'class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        if not root:
            return True
        dummy = TreeNode()
        stack = [[dummy] + [0 for _ in range(5)],[root, 0, False, 0, 0]]
        while len(stack) > 1:
            cur, kidsSeen, is_left, left_height, right_height = stack[-1]
            if kidsSeen == 2:
                if abs(left_height - right_height) > 1:
                    return False
                height = max(left_height, right_height) + 1
                if is_left:
                    stack[-2][3] = height
                else:
                    stack[-2][4] = height
                stack.pop()
            elif kidsSeen == 0:
                stack[-1][1] = 1
                if cur.left:
                    stack.append([cur.left, 0, True, 0, 0])
            elif kidsSeen == 1:
                stack[-1][1] = 2
                if cur.right:
                    stack.append([cur.right, 0, False, 0, 0])
        return True', N'Python Iterative | 89.93 % Runtime | 98.57 % Memory', 628, 110, 216);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (794, N'class Solution:
