INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (795, N'class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:

        def recursive(node: TreeNode, curr_depth: Optional[int] = 0) -> int:
            curr_depth += 1

            if not(node.left) and not(node.right): return curr_depth

            left_depth = right_depth = curr_depth

            if node.left:
                left_depth = recursive(node.left, curr_depth)
                if left_depth == -1: return -1

            if node.right:
                right_depth = recursive(node.right, curr_depth)
                if right_depth == -1: return -1

            if abs(left_depth - right_depth) <= 1:
                return max(left_depth, right_depth)
            else:
                return -1


        if not root: return True

        return recursive(root) != -1', N'Python3 | 56 ms | Beats 91.7% | Recursion', 407, 110, 15);
