INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (799, N'class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
		#check if root is []
        if not root:
            return True
		#Problem: 104.Maximum Depth of Binary Tree
        def maxDepth(root: Optional[TreeNode]):
            return 0 if not root else 1+max(maxDepth(root.left), maxDepth(root.right))
        #Problem: 94.Binary Tree Inorder Traversal
			#a little bit modification: store every node instead of the value of node
        ans=[]
        stack=[]
        while True:
            if root is not None:
                stack.append(root)
                root=root.left
            elif stack:
                root=stack.pop()
                ans.append(root)
                root=root.right
            else:
                break
        #check every node
        for i in range(len(ans)):
            if abs(maxDepth(ans[i].left)-maxDepth(ans[i].right)) > 1:
                return False
        
        return True', N'easy-understand: combination of previous 2 problems(94 & 104)', 72, 110, 36);
