INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (803, N'class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        heightDict = {}
        
        if not root:
            return True
        
        def checkBalance(root: TreeNode) -> bool:
            leftHeight = 0
            rightHeight = 0
            
            if root.left:
                rootLeftCheck = checkBalance(root.left)
                if not rootLeftCheck:
                    return False
                leftHeight = heightDict[root.left]

            if root.right:
                rootRightCheck = checkBalance(root.right)
                if not rootRightCheck:
                    return False
                rightHeight = heightDict[root.right]

            if rightHeight - leftHeight > 1 or leftHeight - rightHeight > 1:
                return False
            else:
                # add current height into dict:
                rootHeight = max(leftHeight, rightHeight) + 1
                heightDict[root] = rootHeight
                return True
            
        return checkBalance(root)', N'SIMPLE 96.45% Faster, Python - recursive', 206, 110, 117);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (804, N'class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        
        if not root:
            return True
        
        def recur(node, level):
            if not node:
                return level-1
            left = recur(node.left, level+1)
            right = recur(node.right, level+1)
            if not left or not right:
                return 0
            if abs(left-right) > 1:
                return 0
            return max(left, right)
        
        level = recur(root, 1)
        
        if not level:
            return False
        return True', N'Python, runtime 60.80%, memory 29.46%', 211, 110, 167);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (805, N'class Solution(object):
    def minDepth(self, root):
        # Base case...
        # If the subtree is empty i.e. root is NULL, return depth as 0...
        if root is None:  return 0
        # Initialize the depth of two subtrees...
        leftDepth = self.minDepth(root.left)
        rightDepth = self.minDepth(root.right)
        # If the both subtrees are empty...
        if root.left is None and root.right is None:
            return 1
        # If the left subtree is empty, return the depth of right subtree after adding 1 to it...
        if root.left is None:
            return 1 + rightDepth
        # If the right subtree is empty, return the depth of left subtree after adding 1 to it...
        if root.right is None:
            return 1 + leftDepth
        # When the two child function return its depth...
        # Pick the minimum out of these two subtrees and return this value after adding 1 to it...
        return min(leftDepth, rightDepth) + 1;    # Adding 1 is the current node which is the parent of the two subtrees...', N'Very Easy || 100% || Fully Explained (C++, Java, Python, JS, C, Python3)', 611, 111, 2200);
