INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (807, N'class Solution:
    def minDepth(self, root: TreeNode) -> int:
        
        if not root:
			# base case for empty node or empty tree
            return 0
        
        if not root.left and not root.right:
			# leaf node
            return 1
        
        elif not root.right:
			# only has left sub-tree
            return self.minDepth(root.left) + 1
        
        elif not root.left:
			# only has right sub-tree
            return self.minDepth(root.right) + 1
        
        else:
			# has left sub-tree and right sub-tree
            return min( map(self.minDepth, (root.left, root.right) ) ) + 1', N'Python O(n) by DFS and BFS 85%+ [w/ Comment]', 303, 111, 2200);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (808, N'class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        def recurse(root):
            if root.left is None and root.right is None:
                return 1
            if root.left is None and root.right:
                return 1+recurse(root.right)
            if root.left and root.right is  None:
                return 1+recurse(root.left)
            if root.left and root.right:
                return min(1+recurse(root.right),1+recurse(root.left))
        return recurse(root) if root else 0', N'Python3 || Recursive || Self-Understandable || Easy-Understanding', 116, 111, 684);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (809, N'class Solution:
    def minDepth(self, root: TreeNode) -> int:
        if not root:
            return 0  # return 0 as depth if empty tree
        elif not root.left and not root.right:
            return 1 # base case handling
        elif not root.left:
            return self.minDepth(root.right)+1 # if no left child then only path is right, so consider right depth
        elif not root.right:
