INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (814, N'class Solution:
    def minDepth(self, root: TreeNode) -> int: 
		
		# Readable BFS
		# T: O(N)
		# S: O(N)
		
        if not root:
            return 0
        if not root.left and not root.right:
            return 1
        
        queue = [root]
        depth = 1
        
        while queue:
            for _ in range(len(queue)):
                node = queue.pop(0)
                if not node.left and not node.right:
                    return depth
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            depth += 1
        return depth', N'Python Easiest to read BFS', 208, 111, 218);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (815, N'class Solution:
