INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (821, N'class Solution:
    def minDepth(self, root: TreeNode) -> int:
        
        if not root: return 0
        if (not root.left) and (not root.right):
            return 1
        
        h = 1
        minimum = float(''inf'')
        
        def calc_minDepth(node, h, minimum):
            
            if h > minimum:
                return minimum
            
            if not node:
                return float(''inf'')
            
            if (not node.left) and (not node.right):
                minimum = min(minimum, h)
                return minimum
            
            return min(calc_minDepth(node.left, 1 + h, minimum), calc_minDepth(node.right, 1 + h, minimum))
            
        return calc_minDepth(root, h, minimum)', N'[Python/Python3] Minimum Depth of Binary Tree', 623, 111, 691);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (822, N'class Solution:
    def minDepth(self, root: TreeNode) -> int:
        if not root:
            return 0
        
        stack = [(root, 1)]
        minDepth = float(''inf'')
        
        while stack:
            node, depth = stack.pop()
            
            if depth >= minDepth:
                continue
            
            if not node.left and not node.right:
                minDepth = min(minDepth, depth)
                
            else:
                if node.left:
                    stack.append((node.left, depth + 1))
                if node.right:
                    stack.append((node.right, depth + 1))
                    
        return minDepth', N'Python Iterative DFS with Optimization', 342, 111, 113);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (823, N'class Solution:
    def minDepth(self, root: TreeNode) -> int:
        
        def fn(node):
            """Return minimum depth of given node"""
            if not node: return 0
            if not node.left or not node.right: return 1 + fn(node.left) + fn(node.right)
            return 1 + min(fn(node.left), fn(node.right))
        
        return fn(root)', N'[Python3] concise solutions', 4, 111, 61);
