INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (826, N'class Solution:
    def minDepth(self, root: TreeNode) -> int:
        if not root: return 0 # edge case 
        
        ans, queue = 1, [root]
        while queue: # bfs by level 
            newq = []
            for n in queue: 
