INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (829, N'class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        # root is a child of a leaf
        if not root:
            return 0

        # root is not a leaf but has a branch missing
        # so mindepth is depth of non-missing branch instead of min(0, depth)
        if not root.left:
            return 1 + self.minDepth(root.right)
        if not root.right:
            return 1 + self.minDepth(root.left)

        # root is not a leaf
        return 1 + min(self.minDepth(root.left), self.minDepth(root.right))', N'Python super simple recursion with explanation', 278, 111, 1);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (830, N'class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        # if tree empty
        if not root:
            return 0
        # queue of tuples: (node, curr depth)
        q = deque([(root, 0)])
        # while q not empty
        while(q):
            # get front of queue
            cur, lvl = q.popleft()
            # if neither child exists, leaf node found
            if not cur.left and not cur.right:
                return (lvl + 1) 
            # if left child exists
            if cur.left:
                # enqueue it
                q.append((cur.left, (lvl + 1)))
            # if right child exists
            if cur.right:
                # enqueue it
                q.append((cur.right, (lvl + 1)))', N'simple python || bfs', 29, 111, 4);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (831, N'class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        if root is None:
            return 0
        def bfs(root,count):
            if root.left and root.right:
                return min(bfs(root.left,count+1),bfs(root.right,count+1))
            elif root.left and not root.right:
                return bfs(root.left,count+1)
            elif root.right and not root.left:
                return bfs(root.right,count+1)
            else:
                return count

        return bfs(root,1)', N'Intuitive + Recursive Python Solution', 173, 111, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (832, N'class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        res = 10**6
        def dfs(root, d1):
            nonlocal res
            if not root:
                return 10**6

            if not root.left and not root.right:
                res = min(res, d1)
