INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (835, N'class Solution:
    def minDepth(self, root):
        if root == None:
            return 0
        
        def DFS(root, mn = 100001, currentCount = 0):
            if root == None:
                return mn
            
            currentCount += 1
            
            if root.left == None and root.right == None and currentCount < mn:
                mn = currentCount
            
            left = DFS(root.left, mn, currentCount)
            right = DFS(root.right, mn, currentCount)
            
            if left < right:
                return left
            return right
            
        return DFS(root)', N'Python currentCount solution, O(n) time complexity and O(h) space complexity.', 548, 111, 34);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (836, N'class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        # we should solve this using bfs, since the node
        # we are trying to find is closes to the root
        if root is None:
            return 0
        
        queue = [(root, 1)]
        while queue:
            
            # pop the most recent node
            current, level = queue.pop(0)
            
            # check whether it has no children
            if current.left is None and current.right is None:
                return level
            
            # insert children
            if current.left is not None:
                queue.append((current.left, level+1))
            if current.right is not None:
                queue.append((current.right, level+1))', N'[Python] - Concise BFS Solution - O(logN)', 44, 111, 79);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (837, N'class Solution:
