INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (845, N'class Solution:
    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        def dfs(node,sum):
            if not node: return False   #base case for null node
            if sum+node.val == targetSum and not node.left and not node.right: return True #when we find the ans
            lt, rt = dfs(node.left,sum+node.val), dfs(node.right,sum+node.val) #recursive steps
            return lt or rt
        return dfs(root,0)', N'?|| Python|| FASTEST AND SIMPLEST|| 7-liner ||recursive|| Easy to Understand', 535, 112, 72);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (846, N'class Solution:
