INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (878, N'class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        if root is None:  # Corner case
            return []
        
        # Initialize variables
        result = []  
        deq = deque()
        
        # Start traversal
        # Every element of deque is a state describing current node
        # As a state we need the following: node itself, remaining sum, path from the root
        deq.append((root, targetSum, []))
        
        # Breath-first-search part
        while deq:
            node, left_sum, path = deq.popleft()
            
            left_sum -= node.val
            path.append(node.val)
            
            if node.left or node.right:  # Try to go into children
                if node.left:
                    deq.append((node.left, left_sum, path.copy()))
                    
                if node.right:
                    deq.append((node.right, left_sum, path.copy()))
            elif left_sum == 0:  # End of a traversal, check if the total path sum is equal to 0
                result.append(path)  # Put path values into the result
        
        return result', N'Python3, breath first search solution, easy to understand', 135, 113, 30);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (879, N'class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        ans = []
        if root: 
            mp = {root: None}
            stack = [(root, 0)]
            while stack: 
                node, val = stack.pop()
                val += node.val 
                if node.left: 
                    mp[node.left] = node
                    stack.append((node.left, val))
                if node.right: 
                    mp[node.right] = node 
                    stack.append((node.right, val))
                if not node.left and not node.right and val == targetSum: 
                    path = []
                    while node: 
                        path.append(node.val)
                        node = mp[node]
                    ans.append(path[::-1])
        return ans', N'[Python3] dfs', 4, 113, 38);
