            if not node.left and not node.right:
                if sum(path + [node.val]) == targetSum: self.ans.append(path + [node.val])
                return
            
            dfs(node.left, path + [node.val])
            dfs(node.right, path + [node.val])
            
            
        dfs(root, [])
        return self.ans', N'Python 10 lines DFS', 205, 113, 155);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (881, N'class Solution:
    def pathSum(self, root: TreeNode, targetSum: int) -> List[List[int]]:

        def dfs(n: TreeNode, s: int):
            if (None, None) == (n.left, n.right) and s == targetSum:
                yield [n.val]
            else:
                yield from ([n.val] + path for c in (n.left, n.right) if c for path in dfs(c, (s + c.val)))
        
        return list(dfs(root, root.val)) if root else []', N'DFS using generator with 5 lines in Python 3', 433, 113, 38);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (882, N'class Solution:
    def pathSum(self, root: TreeNode, sum: int) -> List[List[int]]:
        if not root: return []
        
        if not root.left and not root.right:
            # leaf node
            if root.val == sum:
                return [[root.val]]
            else:
                return []
        
        left = self.pathSum(root.left, sum-root.val)
        right = self.pathSum(root.right, sum-root.val)
        
        left = list(map(lambda xs: [root.val, *xs], left))
        right = list(map(lambda xs: [root.val, *xs], right))
        
        return left + right', N'Elegant solution using a single function [Python] [DFS]', 440, 113, 56);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (883, N'class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        curr = []  # contains current traversing path
        out = []  # contains all found paths
        def t(node):
            if not node: return  # node is null
            curr.append(node.val)  # append this node to current path
            
            # if node is a leaf and path is valid, copy it to <out>
            if (not node.left) and (not node.right) and sum(curr)==targetSum:
                out.append(curr.copy())
            else:
				t(node.left)  # traverse left tree
				t(node.right)  # traverse right tree
            curr.pop()  # remove this node from current path and return
        
        t(root)
        return out', N'Python3 recursive solution', 515, 113, 3);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (884, N'class Solution:
