INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (909, N'class Solution:
    def flatten(self, root: TreeNode) -> None:
        """
        Do not return anything, modify root in-place instead.
        """
        # curr = TreeNode(0)
        if not root:
            return None
        stack = [root]
        while len(stack)>0:
            temp = stack.pop()
			# here, first we will iteratively add both the child of the current node in our stack
            if temp.right:
                stack.append(temp.right)
            if temp.left:
                stack.append(temp.left)
			#to mark the beginning of our flattened linkedlist
            if temp==root:     
                curr = root
				#in each case, left child will be none
                curr.left = None   
            else:
                curr.right = temp
				#in each case, left child will be none
                curr.left = None        
                curr = curr.right', N'Python iterative solution, using preorder', 255, 114, 170);
