INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (914, N'class Solution:
    def flatten(self, root: Optional[TreeNode]) -> None:
        def helper(root):
            if not root:
                return None
            
            # get leaf 
            left = helper(root.left)
            right = helper(root.right)
            
            # left leaf move to right subtree
            root.left = None
            root.right = left
            
            # because we add left subtree to right substree, we need to get the right node of 
            # the previous right substree
            node = root
            while node.right:
                node = node.right
                
            node.right = right
            return root
        
        helper(root)', N'python | recursion', 630, 114, 9);
