INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (916, N'class Solution:
	def flatten(self, root: Optional[TreeNode]) -> None:

		if not root: return root
		elif not root.left and not root.right: return root

		stack, nums = [root], []

		while stack:
			node = stack.pop()

			if node:
				nums.append(node)

				stack.append(node.right)
				stack.append(node.left)

		cursor = root

		for i in nums[1:]:
			cursor.left = None
			cursor.right = i
			cursor = cursor.right', N'Easy-peasy Solution in Python 3, which cannot be difficult', 333, 114, 38);
