INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (919, N'class Solution:

    def flatten(self, root: Optional[TreeNode]) -> None:
        """
        Do not return anything, modify root in-place instead.
        """
        # Depth-first recursion
        def dfs(node):
            # Recursion base case
            # do nothing if none
            if not node:
                return
            # Check for leaf
            elif not node.left and not node.right:
                # Return leafs
                return node

            # Flatten left and right subtrees
            node_left = dfs(node.left)
            node_right = dfs(node.right)
            
            # Switch left subtree to the right
            if node_left:
                # Get to end of right subtree
                # Maintain head
                head = node_left
                while node_left.right:
                    node_left = node_left.right
                # Add right subtree to end of left subtree
                node_left.right = node.right
                # Set right to head of left subtree
                node.right = head
                # Remove left subtree
                node.left = None
			# Return flattened subtree
            return node
        # Flatten Tree
        dfs(root)', N'Easy Python With Explanation DFS w/Recursion', 217, 114, 17);
