INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (921, N'class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
class Solution:
    def flatten(self, root: Optional[TreeNode]) -> None:
        """
        Do not return anything, modify root in-place instead.
        """
        def flatten(n):
            tail =  n
            tmp = n.right
            if n.left: 
                tail = flatten(n.left)
                n.right = n.left
                n.left = None
            if tmp:
                newtail = flatten(tmp)
                tail.right = tmp
                return newtail
            return tail
        
        if root:
            flatten(root)', N'Very simple and short python code', 60, 114, 5);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (922, N'class linkedlist:
    def __init__(self):
        self.head = None
        self.tail = None

def flatten(self, root: Optional[TreeNode]) -> None:
    """
    Do not return anything, modify root in-place instead.
    """
    if root == None:
        return root
    result = self.helper(root)
    
    return result.head

def helper(self, root):
    ll = self.linkedlist()
    
    # base case
    if root.left == None and root.right == None:
        ll.head = ll.tail = root
    
    elif root.left != None and root.right== None:
        temp = self.helper(root.left)
        ll.head = root
        root.right = temp.head
        ll.tail = temp.tail
    
    elif root.left == None and root.right != None:
        temp = self.helper(root.right)
        ll.head = root
        root.right = temp.head
        ll.tail = temp.tail

    else:
        templeft = self.helper(root.left)
        tempright = self.helper(root.right)
        
        ll.head = root
        root.right = templeft.head
        templeft.tail.right = tempright.head
        ll.tail = tempright.tail
		
    root.left = None
    
    return ll', N'Beginner''s Solution - Python', 81, 114, 18);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (923, N'class Solution:
    def flatten(self, root: Optional[TreeNode]) -> None:
        # flatten given root of binary tree and return the tail of linked list
        def recursive(node) -> Optional[TreeNode]:
            if node:
                # these will be leaf nodes of the given subtrees/linked list
                tailLeft = recursive(node.left)
                tailRight = recursive(node.right)
                
                if tailLeft:
                    # Set node''s left subtree to its right, and then make it null
                    tailLeft.right = node.right
                    node.right = node.left
                    node.left = None

                # return leaf node of the linked list
                return tailRight or tailLeft or node
        
        recursive(root)', N'[Python] 39ms || Simple Recursive 2-Tail Pointers - Space O(1) || Documented', 519, 114, 4);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (924, N'class Solution:
    def flatten(self, root: Optional[TreeNode]) -> None:
        """
        Do not return anything, modify root in-place instead.
        """
        if not root:
            return None
        
        # left is the last node of the left subtree.
        # and similarly right is the last node of the right subtree
        left = self.flatten(root.left)
        right = self.flatten(root.right)
        
        if left:
            # First, we join the last node of left subtree to first node in right subtree
            # Then we move the left subtree to the right of the node, and delete the left subtree pointer
            left.right = root.right
            root.right = root.left
            root.left = None
        
        # if theres a right subtree, we return its last node, failing which the last node of the left subtree,
		# and if none are present (i.e. its a leaf node), we return the node itself.
        return right or left or root', N'Python simple commented recursive solution', 328, 114, 12);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (925, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m = len(s)
        n = len(t)
        dp = [[0] * (n+1) for _ in range(m+1)]
        
        for i in range(m+1):
            dp[i][0] = 1
        
        """redundant, as we have initialised dp table with full of zeros"""
#         for i in range(1, n+1): 
#             dp[0][i] = 0
        
        for i in range(1, m+1):
            for j in range(1, n+1):
                dp[i][j] += dp[i-1][j] 			#if current character is skipped
                if s[i-1] == t[j-1]:
                    dp[i][j] += dp[i-1][j-1]	#if current character is used
        
        return dp[-1][-1]', N'Python - Bottom up DP - Explained', 494, 115, 475);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (926, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        ## RC ##
		## APPROACH : DP ##
		## LOGIC ##
		#	1. Point to be noted, empty seq is also subsequence of any sequence i.e "", "" should return 1. so we fill the first row accordingly
		#	2. if chars match, we get the maximum of [diagonal + upper, upper + 1] (Try below example)
		#	3. if no match, we pull the upper value
		
        ## EXAMPLE : "axacccax" "aca"	##
		## STACK TRACE ##
        # [      ""  a  c  a
        #     "" [1, 0, 0, 0], 
        #     a  [1, 1, 0, 0], 
        #     x  [1, 1, 0, 0], 
        #     a  [1, 2, 0, 0], 
        #     c  [1, 2, 2, 0], 
        #     c  [1, 2, 4, 0], 
        #     c  [1, 2, 6, 0], 
        #     a  [1, 3, 6, 6], 
        # ]
        
		## TIME COMPLEXITY : O(MxN) ##
		## SPACE COMPLEXITY : O(MxN) ##

        dp = [[0] * (len(t)+1) for _ in range(len(s)+1)]
        
        for k in range(len(dp)):
            dp[k][0] = 1
        
        for i in range(1, len(dp)):
            for j in range(1, len(dp[0])):
                if(s[i-1] == t[j-1] and dp[i-1][j-1]):
                    dp[i][j] = max(dp[i-1][j-1] + dp[i-1][j], dp[i-1][j]+1)
                else:
                    dp[i][j] = dp[i-1][j]
        # print(dp)
        return dp[-1][-1]', N'O(n)time/BEATS 99.97% MEMORY/SPEED 0ms MAY 2022', 478, 115, 231);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (927, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        def disSub(s,t,ind_s,ind_t,dp):
            if ind_t<0:
                return 1
            if ind_s<0:
                return 0


            if s[ind_s]==t[ind_t]:
                if (dp[ind_t])[ind_s]!=-1:
                    return (dp[ind_t])[ind_s]
                else:
                    (dp[ind_t])[ind_s]=(disSub(s,t,ind_s-1,ind_t-1,dp) + disSub(s,t,ind_s-1,ind_t,dp))
                    return (dp[ind_t])[ind_s]

            (dp[ind_t])[ind_s]=disSub(s,t,ind_s-1,ind_t,dp)
            return (dp[ind_t])[ind_s]






        ls=len(s)
        lt=len(t)
        dp=[[-1]* ls for i in range(lt)]
        return disSub(s,t,ls-1,lt-1,dp)', N'Linear order Python Easy Solution', 545, 115, 176);
