INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (935, N'class Solution:
    def solve(self , s , t, i , j):
        if j == 0:
            return 1
        if i == 0:
            return 0
        if s[i-1] == t[j-1]:
            take = self.solve(s , t, i-1 , j-1)
            move =   self.solve(s , t , i-1 , j)
            return (take + move)
        else:
            return self.solve(s , t, i-1 , j)
    def numDistinct(self, s: str, t: str) -> int:
        return self.solve(s , t , len(s) , len(t))

""" Top - down """

class Solution:
    def solve(self , s , t, i , j , memo):
        if j == 0:
            return 1
        if i == 0:
            return 0
        if memo[i][j] != -1:
            return memo[i][j]
        if s[i-1] == t[j-1]:
            take = self.solve(s , t, i-1 , j-1 , memo)
            move =   self.solve(s , t , i-1 , j , memo)
            memo[i][j] =  (take + move)
            return memo[i][j]
        else:
            memo[i][j]  =  self.solve(s , t, i-1 , j , memo)
            return memo[i][j]
    def numDistinct(self, s: str, t: str) -> int:
        memo = [[-1 for j in range(len(t)+1)] for i in range(len(s)+1)]
        return self.solve(s , t , len(s) , len(t) , memo)

""" Bottom - up """
class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        dp = [[0 for j in range(len(t)+1)] for i in range(len(s)+1)]
        for i in range(len(t)+1):
            dp[0][i] = 0
        for i in range(len(s)+1):
            dp[i][0] = 1
        for i in range(1 , len(s)+1):
            for j in range(1 , len(t)+1):
                if s[i-1] == t[j-1]:
                    take = dp[i-1][j-1]
                    move = dp[i-1][j]
                    dp[i][j] = (take + move)
                else:
                    dp[i][j] = dp[i-1][j]
        return dp[len(s)][len(t)]', N'Python  Three approach recursion , top-down , bottom-up', 149, 115, 4);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (936, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m=len(s)
        n=len(t)
        dp=[]
        for i in range (m+1): #making dp of m+1 and n+1
            dp.append([0]*(n+1))
        dp[0][0]=1          #making 1st element of 2d dp as 1
        for i in range (m+1):    #making 1st column of every row as 1
            dp[i][0]=1
        for i in range (1,n+1):   #making all column as 0 of 1st row leaving first element as it already set to 1
            dp[0][i]=0
        for i in range (1,m+1):
            for j in range (1,n+1):
                if s[i-1]==t[j-1]:     #checking if s and t if both equal then add (the previous diagonal element of dp) and (one row before of the same column) i.e [i-1][j] 
                    dp[i][j]=dp[i-1][j]+dp[i-1][j-1]
                else:
                    dp[i][j]=dp[i-1][j]         # if not equal then copy the previous i-1 element of the same row in dp 
        return dp[m][n]', N'PYTHON|| EASY SOLU|| with EXPLAINATION using DP Bottomup approach', 320, 115, 8);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (937, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        ls, lt = len(s), len(t)
        if ls < lt:
            return 0
        # dp
        subseqs = [[0] * (ls + 1) for _ in range(lt + 1)]
        subseqs[0] = [1] * (ls + 1)
            
        letters_seen = set()
        for ti in range(lt):
            letters_seen.add(t[ti])
            for si in range(ti, ls):
                left = subseqs[ti + 1][si]
                up_left = subseqs[ti][si]
                up = subseqs[ti][si + 1]
                
                # always add value from 1 letter back in s, it will never decrease from there
                subseqs[ti + 1][si + 1] = left
                
                # if they match, add min of 1 letter back in t,  1 letter back in both strings
                # (this min check ensures that we will not count duplicates)
                if t[ti] == s[si]:
                    subseqs[ti + 1][si + 1] += min(up_left, up)
  
        return subseqs[lt][ls]', N'Clean, Fast Python3 | Bottom Up DP | O(s + t)', 254, 115, 9);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (938, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        
        n, m = len(s), len(t)
        lookup = {}
        
        def f(i, j, lookup):
            
            if j<0: return 1
            if i<0: return 0
            
            if (i, j) in lookup: return lookup[(i,j)]
            #matching case
            if s[i] == t[j]:
                lookup[(i,j)] = f(i-1, j-1, lookup) + f(i-1, j, lookup)
                return lookup[(i,j)]
            
            lookup[(i,j)] = f(i-1, j, lookup)
            return lookup[(i,j)]
        return f(n-1, m-1, lookup)', N'Memoization & Recursion', 349, 115, 16);
