INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (940, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        d = {}
        def r(index_s, index_t):
            if index_t < 0:
                return 1
            if index_s < 0:
                return 0
            if s[index_s] == t[index_t]:
                if (index_s-1, index_t-1) not in d:
                    moveTIndex = r(index_s-1, index_t-1)
                else:
                    moveTIndex = d[(index_s-1, index_t-1)]
                if (index_s-1, index_t) not in d:
                    notMoveTIndex = r(index_s-1, index_t)
                else:
                     notMoveTIndex = d[(index_s-1, index_t)]
                d[(index_s, index_t)] = notMoveTIndex + moveTIndex
                return d[(index_s, index_t)]
            else:
                if (index_s-1, index_t) not in d:
                    x = r(index_s-1, index_t)
                else:
                    x = d[(index_s-1, index_t)]
                d[(index_s, index_t)] = x
                return d[(index_s, index_t)]
        
        return r(len(s)-1, len(t)-1)', N'Python DP Solution', 487, 115, 17);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (941, N'class Solution:
