            if dp[i][j]!=-1:
                return dp[i][j]
            if s[i]==t[j]:
                dp[i][j]=helper(i-1, j-1) + helper(i-1, j)
            else:
                dp[i][j]=helper(i-1, j)
            return dp[i][j]
        return helper(n-1, m-1)
		
		
		
		# Tabulation
		
		n=len(s)
        m=len(t)
        dp=[[0]*(m+1) for i in range(n+1)]
        for i in range(n+1):
            dp[i][0]=1
        for i in range(1, n+1):
            for j in range(1, m+1):
                if s[i-1]==t[j-1]:
                    dp[i][j]=dp[i-1][j-1]+dp[i-1][j]
                else:
                    dp[i][j]=dp[i-1][j] 
        return dp[n][m]', N'Python Solution | Recursion | DP', 612, 115, 40);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (942, N'class Solution:
    def solve(self, x, y, m, n):
        if n == 0:
            return 1
        elif m == 0:
            return 0
        if x[m-1] == y[n-1]:
            return self.solve(x, y, m-1, n-1) + self.solve(x, y, m-1, n)
        else:
            return self.solve(x, y, m-1, n)
    
    def numDistinct(self, s: str, t: str) -> int:
        return self.solve(s, t, len(s), len(t))', N'Python easy to read and understand | dynamic-programming', 71, 115, 21);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (943, N'class Solution:
