INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (944, N'class Solution:
	def numDistinct(self, s: str, t: str) -> int:
		r, c = len(t), len(s)
		dp = [[0]*c for _ in range(r)]

		for i in range(c):
			dp[0][i] = 1 + dp[0][i-1] if t[0] == s[i] else dp[0][i-1]

		for i in range(1, r):
			for j in range(1, c):

				dp[i][j] = dp[i-1][j-1] + dp[i][j-1] if t[i] == s[j] else dp[i][j-1]

		return dp[-1][-1]', N'Python3 || My first DP thought solution ever 83.86% of Python3 submissions', 444, 115, 43);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (945, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:

        # Bottom-up solution
        # T(c)=O(n*m)
        # S(c)=O(n*m)
        
        n=len(s)
        m=len(t)
        dp=[[0 for _ in range(m+1)] for _ in range(n+1)]
        
        for i in range(n+1):
            for j in range(m+1):
                if i==0:
                    dp[i][j]=0
                if j==0:
                    dp[i][j]=1
        for i in range(1,n+1):
            for j in range(1,m+1):
                if s[i-1]==t[j-1]:
                    dp[i][j]=dp[i-1][j-1]+dp[i-1][j]
                else:
                    dp[i][j]=dp[i-1][j]
        return dp[n][m]

        # Memoization solution 
        # T(c)=O(n*m)
        # S(c)=O(n*m)+O(n)
        
        n=len(s)
        m=len(t)
        def solve(i,j):
            dp=[[-1 for _ in range(m)] for _ in range(n)]
            if dp[i][j]!=-1:
                return dp[i][j]
            if j<0 : 
                return 1
            if i<0 : 
                return 0
            if s[i]==t[j]:
                dp[i][j]=solve(i-1,j-1)+solve(i-1,j)
                return dp[i][j]
            else:
                dp[i][j]=solve(i-1,j)
                return dp[i][j]
        return solve(n-1,m-1)', N'easy to understand Memoized and Bottom-up solution', 130, 115, 29);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (946, N'class Solution:
    def distinctSubsequences(self, i, j, s, t, dpCache):
        if j == len(t):
            return 1
        if i == len(s):
            return 0
        if (i, j) in dpCache:
            return dpCache[(i, j)]
        
        if s[i] == t[j]:
            dpCache[(i, j)] = self.distinctSubsequences(i + 1, j + 1, s, t, dpCache) + self.distinctSubsequences(i + 1, j, s, t, dpCache)
        else:
            dpCache[(i, j)] = self.distinctSubsequences(i + 1, j, s, t, dpCache)
        
        return dpCache[(i, j)]
    
    
    def numDistinct(self, s: str, t: str) -> int:
        dpCache = {}
        return self.distinctSubsequences(0, 0, s, t, dpCache)', N'DP || Top Down || Memoization', 556, 115, 36);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (947, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        def get_subsequences(s, t, index_1, index_2, memo):
            if index_1 == len(s):
                if index_2 == len(t):
                    return 1
                return 0
            if index_2 == len(t):
                return 1
            if (index_1, index_2) in memo:
                return memo[(index_1, index_2)]
            ans = 0
            if s[index_1] == t[index_2]:
                # Choose to include this index
                ans += get_subsequences(s, t, index_1 + 1, index_2 + 1, memo)
            # Choose to not include this index 
            ans += get_subsequences(s, t, index_1 + 1, index_2, memo)
            memo[(index_1, index_2)] = ans
            return ans
        return get_subsequences(s, t, 0, 0, {})', N'Python3 clean code (recursion + memoization)', 164, 115, 35);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (948, N'class Solution:
