INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (951, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        memo = {}
        def dfs(i, j):
            if (i,j) in memo:
                return memo[(i,j)]
            
            if j == len(t):
                return 1
            if i == len(s) or len(t)-j > len(s)-i:
                return 0
            
            count = 0
            if s[i] == t[j]:
                count += dfs(i+1, j+1)
            count += dfs(i+1, j)
            
            memo[(i,j)] = count
            return count
            
        return dfs(0,0)', N'Distinct Subsequences || DP', 508, 115, 59);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (952, N'class Solution:
    def numDistinctTopDown(self, s: str, t: str) -> int:
        # this is like edit distance... with only delete ;)
        @functools.cache
        def ways(si, ti): # index in both strings
            if ti == len(t):
                return 1
            elif si == len(s):
                return 0
            
            #  MATCH / include
            match = 0
            if s[si] == t[ti]:
                match = ways(si+1,ti+1)
            
            # SKIP
            skip = ways(si+1, ti)
            
            return match + skip
        
        return ways(0,0) 
    
    # now trying bottom up
    def numDistinct2D(self, s: str, t: str) -> int:
        N,M = len(s), len(t)

        # construct N x M matrix for storing DP results
        ways = [[0 for __ in range(M+1)] for _ in range(N+1)]

        # base case: ti == M
        for si in range(N+1):
            ways[si][M] = 1

        # now iterate backwards since ways[si] -> depends on ways[si+1]
        for si in range(N-1, -1, -1):

            for ti in range(M-1, -1, -1): # ti depends on ti+1 so again backwards

                #  MATCH / include
                match = 0
                if s[si] == t[ti]:
                    match = ways[si+1][ti+1]

                # SKIP
                skip = ways[si+1][ti]

                ways[si][ti] = match + skip

        return ways[0][0]
    
     # now trying bottom up, only store today `i` and tommorrow `i+1` 
    def numDistinct(self, s: str, t: str) -> int: # O(M)
        N,M = len(s), len(t)

        # construct N x M matrix for storing DP results
        ways_today = [0 for _ in range(M+1)]

        # base case: ti == M
        ways_today[M] = 1
        
        ways_tomm = ways_today[:]

        # now iterate backwards since today -> depends on tommorrow
        for si in range(N-1, -1, -1):

            # each value of ti depends on ti+1 so again backwards
            for ti in range(M-1, -1, -1): 

                # MATCH / include
                match = 0
                if s[si] == t[ti]:
                    match = ways_tomm[ti+1]

                # SKIP
                skip = ways_tomm[ti]

                ways_today[ti] = match + skip
            
            # now we do i--, then tomm = i, tomm
            ways_tomm = ways_today[:] 

        return ways_today[0]', N'2 Pointer, Recursion, 2D, 1D iteration Edit distance delete operation ;)', 417, 115, 76);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (953, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        
        @lru_cache(None)
        def fn(i, j): 
            """Return number of subsequences of s[i:] which equals t[j:]"""
            if j == len(t): return 1
            if i == len(s): return 0
            return fn(i+1, j) + (s[i] == t[j]) * fn(i+1, j+1)
        
        return fn(0, 0)', N'[Python3] dynamic programming', 4, 115, 52);
