INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (955, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        nextp = [ {} for _ in range(len(s))]
        current={}
        for i in range(len(s)-1,-1,-1):
            current[s[i]] = i
            nextp[i]=current.copy()
        self.mem={}
        return self.helper(s,0,t,0,nextp)

    def helper(self,s,i,t,j,nextp):
        if (i,j) in self.mem:
            return self.mem[(i,j)]
        
        if j==len(t):
            self.mem[(i,j)]=1
            return 1
        if i==len(s):
            self.mem[(i,j)] = 0
            return 0
        
        if t[j] in nextp[i]:
            self.mem[(i,j)] = self.helper(s,nextp[i][t[j]]+1,t,j,nextp) + self.helper(s,nextp[i][t[j]]+1,t,j+1,nextp)
        else:
            self.mem[(i,j)] = 0
        return self.mem[(i,j)]', N'python solution recursive with memory, beats 99%', 289, 115, 88);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (956, N'class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m, n = len(s), len(t)
        dp = [[0 for i in range(m + 1)] for i in range(n + 1)]
        
        for i in range(0, m + 1):
            dp[i][0] = 1
        for i in range(1,m + 1):
            for j in range(1,n + 1):
                dp[i][j] += dp[i - 1][j] + (dp[i - 1][j - 1] if s[i - 1] == t[j - 1] else 0)
        return dp[m][n]', N'Python O(n^2) solution using DP', 220, 115, 95);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (957, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        # edge case check
        if not root:
            return None
        
        # initialize the queue with root node (for level order traversal)
        queue = collections.deque([root])
        
        # start the traversal
        while queue:
            size = len(queue) # get number of nodes on the current level
            for i in range(size):
                node = queue.popleft() # pop the node
                
                # An important check so that we do not wire the node to the node on the next level.
                if i < size-1:
                    node.next = queue[0] # because the right node of the popped node would be the next in the queue. 
                    
                if node.left:
                    queue.append(node.left) 
                if node.right:
                    queue.append(node.right)           
                
        return root', N'Python Solution O(1) and O(n) memory.', 412, 116, 534);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (958, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        # edge case check
        if not root:
            return None
        
        node = root # create a pointer to the root node
        
        # iterate only until we have a new level (because the connections for Nth level are done when we are at N-1th level)
        while node.left:
            head = node
            while head:
                head.left.next = head.right
                if head.next:
                    head.right.next = head.next.left
                    
                head = head.next
                
            node = node.left

        return root', N'Python Solution O(1) and O(n) memory.', 412, 116, 534);
