INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (965, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        
        def fn(node, i=0):
            """Return tree whose next pointer is populated."""
            if not node: return 
            node.next = seen.get(i)
            seen[i] = node 
            fn(node.right, i+1) and fn(node.left, i+1)
            return node 
            
        seen = {}
        return fn(root)', N'[Python3] O(1) space solution', 4, 116, 96);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (966, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        stack = [(0, root)]
        seen = {}
        while stack: 
            i, node = stack.pop()
            if node: 
                node.next = seen.get(i)
                seen[i] = node 
                stack.append((i+1, node.left))
                stack.append((i+1, node.right))
        return root', N'[Python3] O(1) space solution', 4, 116, 96);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (967, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
