INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (969, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        
        if not root: return None
        
        nodes_at_each_level = []
        level = [root]
        
        while level:
            nodes_at_each_level.append([node for node in level])
            level = [child for node in level for child in (node.left,node.right) if child]
        
        
        # return root
        
        for level_nodes in nodes_at_each_level:
            for idx in range(len(level_nodes)-1):
                level_nodes[idx].next = level_nodes[idx+1]
        
        return root', N'[Python/Python3] Populating Next Right Pointers in Each Node', 623, 116, 195);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (970, N'class Solution:
    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
        
        def rp(parent, child):
            if parent and child:
                if child == parent.left:
                    child.next = parent.right
                elif child == parent.right and parent.next:
                    child.next = parent.next.left
            
            if child:
                rp(child, child.left)
                rp(child, child.right)
        
        rp(None, root)
        return root', N'[Python/Python3] Populating Next Right Pointers in Each Node', 623, 116, 195);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (971, N'class Solution:
    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
	
	#if tree is empty
        if not root:
            return
			
		#if tree has only one value
        if not root.left or not root.right:
            return root
			
        flag = False       #to assign the very first node.next = None
        def dfs(root):
            nonlocal flag

            if not root.left or not root.right:    #if node has no left and right child
                return
				
            if not flag:
                root.next = None
                flag = True
				
            root.left.next = root.right
			
            if not root.next:     # if you have traversed all the node of a particular node
                root.right.next = None
            else:
                root.right.next = root.next.left
				
            dfs(root.left)
            dfs(root.right)
			
        dfs(root)
        return root', N'[Python3] | SC O(1) | 98% Faster 74% less space | Easy-understanding', 41, 116, 56);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (972, N'class Solution:
    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
        parent = root
        nextChild = root.left if root else None

        # traverse the tree parent and next child that will be 
        # required once right side nodes are covered and we come back to this state
        while parent and nextChild:
            parent.left.next = parent.right
            
            # if parent has right side node
            rightSideNode = parent.next
            if rightSideNode:
                parent.right.next = rightSideNode.left

            # next parent will be next right side node
            parent = rightSideNode

            # if there is no next right side node, go downward (next left child)
            if parent == None:
                parent = nextChild
                nextChild = parent.left
                
        return root', N'[Python] Simple Iterative solution - Space O(1) || Documented', 519, 116, 22);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (973, N'class Solution:
    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
        if not root: return
        if root.next:
            if root.right and root.next.left:
                root.right.next = root.next.left
        if root.left and root.right:
            root.left.next = root.right
        self.connect(root.left)
        self.connect(root.right)
        return root', N'[Python3] Intuitive Recursive Approach', 49, 116, 22);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (974, N'class Solution:
