INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (977, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        if not root:
            return root
        from collections import deque
        q = deque([(root, 0)])
        while q:
            n, level = q.popleft()
            q += ((c, level + 1) for c in (n.left, n.right) if c)
            try:
                if level == q[0][1]:
                    n.next = q[0][0]
            except IndexError:
                pass
        return root', N'3 iterative solutions in Python, from O(n) space to O(1)', 433, 116, 145);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (978, N'class Solution:
