INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (980, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        
        # corner case where the tree is empty
        if root:
            # if it''s not a leaf node
            if root.left and root.right:
                # connect the left child to the right child
                root.left.next = root.right
                # if the current node has the next set
                if root.next:
                    # the current right''s next will be the left child of it
                    root.right.next = root.next.left
                # repeat the process recursevely
                self.connect(root.left)
                self.connect(root.right)
        
        return root', N'Python | Recursive approach with no extra space | Explained', 491, 116, 73);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (981, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        if root is None:
            return root
        
        self.traverse(root, None, None)
        return root
    
    def traverse(self, node, parent, goLeft):
        if node is None:
            return 
        
        left, right = node.left, node.right
        self.traverse(left, node, True)
        
        if parent is None:
            # for root
            node.next = None
        elif goLeft:
            node.next = parent.right
        else:
            if parent.next is None:  
                node.next = None
            else:
                node.next = parent.next.left
        
        self.traverse(right, node, False)', N'Python O(1) space with recursion beats 90 speed', 345, 116, 170);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (982, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        if not root:
