INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (983, N'class Solution:
    def dfs(self, root, levels, level):
        if level not in levels:
            levels[level] = []

        if root and root.left:
            levels[level].extend([root.left, root.right])

            self.dfs(root.left, levels, level + 1)
            self.dfs(root.right, levels, level + 1)

    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
        levels = {}
        self.dfs(root, levels, 0)

        for level in levels.keys():
            nodes = levels[level]

            for i in range(len(nodes) - 1):
                nodes[i].next = nodes[i + 1]

        return root', N'Python DFS', 38, 116, 1);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (984, N'class Solution:
    def __init__(self):
        self.hash_table = None

    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
        if root is None:
            return
        self.hash_table = defaultdict(list)
        self.level_order(root, 0)
        for key in self.hash_table:
            if key == 0:
                continue
            last_node = self.hash_table[key][0]
            for current_node in self.hash_table[key][1:]:
                last_node.next = current_node
                last_node = current_node
        return root

    def level_order(self, node, level):
        if node is None:
            return
        self.hash_table[level].append(node)
        self.level_order(node.left, level+1)
        self.level_order(node.right, level+1)', N'Python3 | Hash Map + BFS', 512, 116, 6);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (985, N'class Solution:
    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
        tree = []
        def dfs(node, level=0):
            if node is None:
                return
            
            if len(tree) == level:
                tree.append([])
            dfs(node.right, level + 1)
            dfs(node.left, level + 1)
            if len(tree[level]) > 0:
                node.next = tree[level].pop()
            else:
                node.next = None
            
            tree[level].append(node)
        
        dfs(root)
        
        return root
	```', N'Python3 DFS, recursion! Nodes matched on the same `level`', 65, 116, 31);
