INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (995, N'class Solution:
    def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':
        q1 = []
        q1.append(root)
        level = 0
        if not root:
            return root
        while q1:
            rightMostNodeIndex = 2**level - 1
            q1[rightMostNodeIndex].next = None
            for i in range(rightMostNodeIndex + 1):
                q1[i].next = q1[i + 1] if i+1 <= rightMostNodeIndex else None
                if q1[i].left:
                    q1.append(q1[i].left)
                if q1[i].right:
                    q1.append(q1[i].right)
            q1[:] = q1[rightMostNodeIndex + 1:]
            level += 1
        return root', N'Easy to Understand | Step by Step Explanation', 126, 116, 26);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (996, N'class Solution:
	def connect(self, root: ''Optional[Node]'') -> ''Optional[Node]'':

		if root is None:
			return None

		queue = [root]

		total_node = 1

		while queue:

			count_node = 1

			for i in range(len(queue)):

				node = queue.pop(0)

				if count_node == total_node:
					node.next = None
				else:
					node.next = queue[0]

				if node.left != None:
					queue.append(node.left)

				if node.right != None:
					queue.append(node.right)

