INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (997, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        if not root:
            return None
        q = deque()
        q.append(root)
        dummy=Node(-999) # to initialize with a not null prev
        while q:
            length=len(q) # find level length
            
            prev=dummy
            for _ in range(length): # iterate through all nodes in the same level
                popped=q.popleft()
                if popped.left:
                    q.append(popped.left)
                    prev.next=popped.left
                    prev=prev.next
                if popped.right:
                    q.append(popped.right)
                    prev.next=popped.right
                    prev=prev.next                
                 
        return root', N'Python Easy: BFS and O(1) Space with Explanation', 61, 117, 3000);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (998, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        if not root:
            return None
        
        curr=root
        dummy=Node(-999)        
        head=root        

		while head:
            curr=head # initialize current level''s head
            prev=dummy # init prev for next level linked list traversal
			# iterate through the linked-list of the current level and connect all the siblings in the next level
            while curr:  
                if curr.left:
                    prev.next=curr.left
                    prev=prev.next
                if curr.right:
                    prev.next=curr.right
                    prev=prev.next                                                
                curr=curr.next
            head=dummy.next # update head to the linked list of next level
            dummy.next=None # reset dummy node
        return root', N'Python Easy: BFS and O(1) Space with Explanation', 61, 117, 3000);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (999, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        
        def helper( node: ''Node''):
            
            if not node:
                return None
            
            scanner = node.next

            # Scanner finds left-most neighbor, on same level, in right hand side
            while scanner:

                if scanner.left:
                    scanner = scanner.left
                    break

                if scanner.right:
                    scanner = scanner.right
                    break

                scanner = scanner.next


            # connect right child if right child exists
            if node.right:
                node.right.next = scanner 

            # connect left child if left child exists
            if node.left:
                node.left.next = node.right if node.right else scanner


            # DFS down to next level
            helper( node.right )  
            helper( node.left )  
                
            return node
        # -------------------------------
        
        return helper( root )', N'Python O(1) aux space DFS sol. [with Diagram]', 303, 117, 1500);
INSERT INTO Leetcode.Discussion (id, solution, title, userId, questionId, numberOfViews) VALUES (1000, N'class Solution:
    def connect(self, root: ''Node'') -> ''Node'':
        parents = [root] 
        kids = []
        prev = None
        while len(parents) > 0:
            p = parents.pop(0)
            if prev:
                prev.next = p
            prev = p
            if p:
                if p.left:
                    kids.append(p.left)
                if p.right:
                    kids.append(p.right)
            if len(parents) == 0:
                parents = kids
                kids = []
                prev = None
        return root', N'Python3 - in-place, BFS solution, faster than 97%', 607, 117, 255);

